INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヒヨリ", "", "vo_empress_100101_001", 0, 1, 4, "", 1, 1, 5, 100101, "vo_empress_100101_001", "どんなに敵が大勢でも、みんなで\n力を合わせれば絶対大丈夫だよ！\nだから顔を上げてこう！\nごーごー！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヒヨリ", "", "vo_empress_100101_002", 0, 1, 4, "", 2, 1, 5, 100103, "vo_empress_100101_002", "ううっ、何度も戦う相手もいるけど\nあたし、負けたりなんてしないよ！\n今回だってみんなや騎士くんがいる\nフルパワーでいくよーっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヒヨリ", "", "vo_empress_100101_003", 0, 2, 4, "", 3, 1, 5, 100103, "vo_empress_100101_003", "うぅ…すごい力…！\n…でも、なんだか悲しそう\nこの人の気持ちを知りたい\nだからこそ…勝たなきゃ…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヒヨリ", "", "vo_empress_100101_004", 100101, 3, 4, "", 4, 1, 5, 100102, "vo_empress_100101_004", "騎士くんの力があれば、\nあたしは絶対負けないよ！\nみんなが笑顔でいられるように\n一緒にがんばろう！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユイ", "", "vo_empress_100201_001", 0, 1, 4, "", 5, 1, 5, 100203, "vo_empress_100201_001", "わたしたちの世界のためにも\nこの世界のためにも、\n絶対に負けられない…！\nがんばろうね、騎士クン");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユイ", "", "vo_empress_100201_002", 0, 1, 4, "", 6, 1, 5, 100203, "vo_empress_100201_002", "みんな、怪我したらすぐに教えて！\n…もう誰も失いたくないの\nそのために修行もしたんだから…\n大丈夫、絶対なんとかしてみせる！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユイ", "", "vo_empress_100201_003", 0, 2, 4, "", 7, 1, 5, 100203, "vo_empress_100201_003", "世界を『書き換え』するなんて…\nそんな未来、寂しいだけだよ…！\nお願い、これ以上みんなを\n傷つけないで…話を聞いて！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユイ", "", "vo_empress_100201_004", 100201, 3, 4, "", 8, 1, 5, 100202, "vo_empress_100201_004", "感じるよ、騎士クンの気持ち…\n抱きしめられてるみたいに\nあったかい…\nぜんぶ終わらせよう！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("レイ", "", "vo_empress_100301_001", 0, 1, 4, "", 9, 1, 5, 100301, "vo_empress_100301_001", "厳しい戦いになるだろうな\n安心してくれ、何があっても\nキミは守る。…いや、違うな\n一緒に、世界を守ろう");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("レイ", "", "vo_empress_100301_002", 0, 1, 4, "", 10, 1, 5, 100303, "vo_empress_100301_002", "手ごわい相手ばかりだな…\nだが引き下がるわけにはいかない\nこちらにだって譲れないものが\nあるんだ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("レイ", "", "vo_empress_100301_003", 0, 2, 4, "", 11, 1, 5, 100303, "vo_empress_100301_003", "くっ…なんて力だ…！\n防ぐだけで精一杯…だが、\n例え剣が折れたとしても、\n私は最後まで戦い続ける！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("レイ", "", "vo_empress_100301_004", 100301, 3, 4, "", 12, 1, 5, 100302, "vo_empress_100301_004", "感じるよ、キミからの愛\nこれがあれば、私はどんな\n敵にだって打ち勝てる！\n見せてやろう、一緒に！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミソギ", "", "vo_empress_100401_001", 0, 1, 4, "", 13, 1, 5, 100401, "vo_empress_100401_001", "ミソギとにいちゃんはこれからも\n世界中を冒険して、ワクワクする\nお宝をたくさん見つけるんだ！\nワルモノなんかに邪魔させないよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミソギ", "", "vo_empress_100401_002", 0, 1, 4, "", 14, 1, 5, 100401, "vo_empress_100401_002", "わわ、なんかヤバそうな雰囲気…\nこういう時こそミソギの出番だね！\nとっておきのイタズラ決めて、\nピンチもひっくり返しちゃうよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミソギ", "", "vo_empress_100401_003", 0, 2, 4, "", 15, 1, 5, 100403, "vo_empress_100401_003", "うぅ…あの悪者、すごい迫力だよ…\nもしミソギたちが負けちゃったら、\nミソギもにいちゃんもこの世界も…\n全部おしまい、なんだよね…？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミソギ", "", "vo_empress_100401_004", 100401, 3, 4, "", 16, 1, 5, 100402, "vo_empress_100401_004", "ミソギたちが世界を救っちゃったら\nきっとみんなびっくりするよね！\nどんな顔して驚いてくれるかな…\nにひひ、なんかワクワクしてきた！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("マツリ", "", "vo_empress_100501_001", 0, 1, 4, "", 17, 1, 5, 100501, "vo_empress_100501_001", "歴代オールヒーロー大進撃ッス～！\n自分は新世代のエースってとこッス\nかね？　さあ、ついてくるッス……\nあれ？　みんなどこ？　待って～");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("マツリ", "", "vo_empress_100501_002", 0, 1, 4, "", 18, 1, 5, 100501, "vo_empress_100501_002", "敵は圧倒的な力で、こっちを絶望\nさせる気ッスかね？　だとしたら\n大誤算ッスよ！　むしろ自分の\n正義の魂に火をつけたんスから！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("マツリ", "", "vo_empress_100501_003", 0, 2, 4, "", 19, 1, 5, 100503, "vo_empress_100501_003", "足が……震えるッス……けど！\nこれは武者震いッス……！　だって\nヒーローは絶対に絶対にっ！\n敗北なんてしないんスから……っ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("マツリ", "", "vo_empress_100501_004", 100501, 3, 4, "", 20, 1, 5, 100502, "vo_empress_100501_004", "さあ、手と手をつないで、\n二人で教えてやるッスよ！\nどんな物語でも、悪は必ずヒーロー\nに打ち倒されるってことを！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アカリ", "", "vo_empress_100601_001", 0, 1, 4, "", 21, 1, 5, 100603, "vo_empress_100601_001", "ひゃぁんっ！\nもう、敵さんが脅かしてくるから\nアカリ、ヘンな声出ちゃいました…\nこういうの、よくないですよっ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アカリ", "", "vo_empress_100601_002", 0, 1, 4, "", 22, 1, 5, 100601, "vo_empress_100601_002", "アカリ、お兄ちゃんとシタイコトが\nまだまだいっぱいあるんです！\nだから、私たちの大事な世界も…\n本気で守り抜いてみせますっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アカリ", "", "vo_empress_100601_003", 0, 2, 4, "", 23, 1, 5, 100603, "vo_empress_100601_003", "うぅ…こんなに激しく攻められたら\nアカリ、もう壊れちゃいそうです…\nだけどまだまだ…戦えますっ！\nお兄ちゃんが一緒なんですからっ…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アカリ", "", "vo_empress_100601_004", 100601, 3, 4, "", 24, 1, 5, 100602, "vo_empress_100601_004", "お兄ちゃんの愛を注いでもらって\nアカリ超絶パワーアップです！\nアカリらしく世界一かわいく、\n世界を救ってみせちゃいますよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミヤコ", "", "vo_empress_100701_001", 0, 1, 4, "", 25, 1, 5, 100701, "vo_empress_100701_001", "アイツらが野放しだと、ミヤコは\n安心してプリンを食べられないの\n今日のプリンと明日のプリンの\nためにも、絶対負けないの！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミヤコ", "", "vo_empress_100701_002", 0, 1, 4, "", 26, 1, 5, 100702, "vo_empress_100701_002", "前はミヤコ、悪いヤツに捕まって\n消されそうになって怖かったの…\nでも今度は全然怖くないの！\nオマエが一緒なら平気なの！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミヤコ", "", "vo_empress_100701_003", 0, 2, 4, "", 27, 1, 5, 100703, "vo_empress_100701_003", "むうぅ～っ、アイツしつこいの！\nこうなったら、オマエにも\nミヤコのプリン分けてやるの！\nダブルプリンパワーで頑張るの！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミヤコ", "", "vo_empress_100701_004", 100701, 3, 4, "", 28, 1, 5, 100702, "vo_empress_100701_004", "アイツはどんなに強くたって、\n独りぼっちのさびしいヤツなの\nでもオマエにはミヤコがいるの！\nミヤコたちなら絶対に勝てるの！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユキ", "", "vo_empress_100801_001", 0, 1, 4, "", 29, 1, 5, 100801, "vo_empress_100801_001", "相手が誰であれ、やることは同じ…\nそう…ボクの美しさを見せてあげる\nことさ！　予言しよう…絶世の美の\n前にはどんな敵もひれ伏すと、ね！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユキ", "", "vo_empress_100801_002", 0, 1, 4, "", 30, 1, 5, 100801, "vo_empress_100801_002", "少し待っていてくれる？　メイクを\n直さないと。避けられない戦いなら\nせめて美しいボクと戦えることを\n彼らには誇りに思ってほしいからね");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユキ", "", "vo_empress_100801_003", 0, 2, 4, "", 31, 1, 5, 100801, "vo_empress_100801_003", "どうせ倒れるなら美しいままで散り\nたいな。ふふ、難しい望みかな…？\nそれでもボクは、最後まで美しく\nあがいてみせるよ、キミと一緒にね");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユキ", "", "vo_empress_100801_004", 100801, 3, 4, "", 32, 1, 5, 100802, "vo_empress_100801_004", "ボクがいて、キミがいる。ボクたち\nが勝つのに、これ以上の理由はない\nよね。だって美しい者が勝つ未来の\nほうが、美しいエンディングだもの");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アンナ", "", "vo_empress_100901_001", 0, 1, 4, "", 33, 1, 5, 100901, "vo_empress_100901_001", "災厄の嵐が吹き荒れ、世界の命運は\n風前の灯が如く儚い。だが絶望には\nまだ早い！　希望はここに在り！\n灯火を掲げよう、盟友シグルドよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アンナ", "", "vo_empress_100901_002", 0, 1, 4, "", 34, 1, 5, 100903, "vo_empress_100901_002", "終焉の日、滅びの刻来たれり、か…\nだが、幾度も転生を繰り返しながら\n戦いつづけた我らの宿命を思えば、\nこの程度取るに足らない…はずだ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アンナ", "", "vo_empress_100901_003", 0, 2, 4, "", 35, 1, 5, 100903, "vo_empress_100901_003", "くっ…なんという禍々しい魔力…！\nもはや世界の滅びも間近…しかし\n疾風の冥姫がここで退くわけには\nいかぬ！　しぶとく抗ってみせるぞ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アンナ", "", "vo_empress_100901_004", 100901, 3, 4, "", 36, 1, 5, 100902, "vo_empress_100901_004", "永遠の盟約で結ばれし魂の伴侶…\n世界を滅ぼさんとする災禍の剣も\nこの絆を断ち切ることはできない！\n覚悟するがいい、幻境竜后！！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("マホ", "", "vo_empress_101001_001", 0, 1, 4, "", 37, 1, 5, 101001, "vo_empress_101001_001", "【自警団】のギルドマスターとして\nしゃんとして恥ずかしない姿を\n見せなあきまへんなぁ…王子はん\nしゃなりしゃなり、いきまひょ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("マホ", "", "vo_empress_101001_002", 0, 1, 4, "", 38, 1, 5, 101001, "vo_empress_101001_002", "王子はん、服が破れてますえ？\nこれでよし…うん、完璧や♪\n戦いの中でも、王子はんには\n格好良う居てもらいたいさかいに♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("マホ", "", "vo_empress_101001_003", 0, 2, 4, "", 39, 1, 5, 101003, "vo_empress_101001_003", "幻境竜后…大層なお名前してはる\nお后さまが勝負を挑んできはるなら\nうちも、マホマホ王国の姫として…\n正々堂々受けて立ちますえ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("マホ", "", "vo_empress_101001_004", 101001, 3, 4, "", 40, 1, 5, 101002, "vo_empress_101001_004", "強い愛で結ばれた王子と姫を\n引き裂くことは誰にもできまへん\n王子はん…ふたりで一緒に！\nハッピーエンドを迎えまひょ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リノ", "", "vo_empress_101101_001", 0, 1, 4, "", 41, 1, 5, 101101, "vo_empress_101101_001", "お兄ちゃんがいれば百人力士っ！\n妹パワーも全開でいきますよ～♪\nどんな敵でもドンドンこいですっ！\nあれ？　ちょっと違いました？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リノ", "", "vo_empress_101101_002", 0, 1, 4, "", 42, 1, 5, 101101, "vo_empress_101101_002", "これぞまさに『四面そば』…\n敵多すぎでもう大盛りですけど\n秘密結社の一員として、妹として\nこの世界の平和は守り通しますっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リノ", "", "vo_empress_101101_003", 0, 2, 4, "", 43, 1, 5, 101103, "vo_empress_101101_003", "あれが幻境竜后…不思議な服…\nじゃなくて、空気がピリピリです…\nちょっとだけ怖いけど…妹として\n絶対に降参なんてしませんよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リノ", "", "vo_empress_101101_004", 101101, 3, 4, "", 44, 1, 5, 101102, "vo_empress_101101_004", "私、もう迷いません！\nお兄ちゃんと一緒なら\nどんな敵だって倒しちゃいます！\n妹のポテンシャルは無限大ですよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ハツネ", "", "vo_empress_101201_001", 0, 1, 4, "", 45, 1, 5, 101201, "vo_empress_101201_001", "どんなに大変な時でもキミと一緒に\nず～っと乗り越えてきたんだもん！\nだからっ、今回もきっと大丈夫！\n私の魔法できらーん☆　だよっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ハツネ", "", "vo_empress_101201_002", 0, 1, 4, "", 46, 1, 5, 101202, "vo_empress_101201_002", "力を使いすぎると眠く…スヤァ…\nはっ、いけないいけない！\nキミ、私が寝ちゃったら起こして！\n…お、王子様のキスとかで…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ハツネ", "", "vo_empress_101201_003", 0, 2, 4, "", 47, 1, 5, 101203, "vo_empress_101201_003", "も～！　容赦なさすぎだよぉ！\nそっ、それにさっきまでの戦いの\nせいで、ね、眠気がぁ～っ…\nハ、ハツネちゃん、ピ～ンチ…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ハツネ", "", "vo_empress_101201_004", 101201, 3, 4, "", 48, 1, 5, 101202, "vo_empress_101201_004", "幻境竜后さんがどんなに強くても\n今のハツネちゃんは無敵なのだ～！\n大好きなキミと！　シオリンと！\nみんながいる世界を守っちゃうよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ナナカ", "", "vo_empress_101301_001", 0, 1, 4, "", 49, 1, 5, 101301, "vo_empress_101301_001", "この世界にはね、たくさんの人の\n『好き』が詰まってるんだよ\nそれをぶち壊すなんて鬼畜の所業\nナナカちゃんが許しはしないぜ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ナナカ", "", "vo_empress_101301_002", 0, 1, 4, "", 50, 1, 5, 101301, "vo_empress_101301_002", "見るからにヤバい奴らが勢ぞろい！\nでもみんなの世界が狙われてんのに\n日和ってる奴いる？いねえよなぁ！\n全員ぶっ飛ばして世界を救うぞ！！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ナナカ", "", "vo_empress_101301_003", 0, 2, 4, "", 51, 1, 5, 101303, "vo_empress_101301_003", "あとはラスボスを倒せば勝利ッ！\n第３部完！　…とはいかない感じ？\nていうか逆にピンチな気配？\nどっどうしよう、どうすれば！？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ナナカ", "", "vo_empress_101301_004", 101301, 3, 4, "", 52, 1, 5, 101302, "vo_empress_101301_004", "幻境竜后…確かに強敵だったね\nでも今はもう負ける気がしないかな\nだって私は、ただのナナカじゃない\n超ナナカちゃんだから…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カスミ", "", "vo_empress_101401_001", 0, 1, 4, "", 53, 1, 5, 101401, "vo_empress_101401_001", "あちらにもなかなかの陰謀家がいる\nようだね。彼女らの最大の誤算は\nここに希代の名探偵がいることさ！\nさあ助手くん。真実を勝ち取ろう！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カスミ", "", "vo_empress_101401_002", 0, 1, 4, "", 54, 1, 5, 101401, "vo_empress_101401_002", "仕方ない、こうなったら奥の手だ\nミスティ！　セオリー！　…って\nこらぁっ！　変身の最中は待って\nくれるのがお約束だよ！？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カスミ", "", "vo_empress_101401_003", 0, 2, 4, "", 55, 1, 5, 101403, "vo_empress_101401_003", "なっ…なんだい、この悪寒は…\n触れてはならない何か…いいや！\n名探偵たるもの巨悪に恐れをなす\nわけにはいかない。絶対に…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カスミ", "", "vo_empress_101401_004", 101401, 3, 4, "", 56, 1, 5, 101402, "vo_empress_101401_004", "どんな哀しみでさえ、道理を穢す\n理由にしてはならない。さあ、\nお縄につくんだ。史上最大の迷宮\n事件…終わらせるのは…この私だ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミサト", "", "vo_empress_101501_001", 0, 1, 4, "", 57, 1, 5, 101501, "vo_empress_101501_001", "先生は…ううん、先生たちは。\n絶対に負けません。みんなに傷一つ\nつけさせたりはしないわ…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミサト", "", "vo_empress_101501_002", 0, 1, 4, "", 58, 1, 5, 101501, "vo_empress_101501_002", "とっても強大な敵ばかりね…\nでも、大丈夫。焦らず落ち着いて\n戦いましょう。先生がついてるわ\n長引いても、あきらめないで…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミサト", "", "vo_empress_101501_003", 0, 2, 4, "", 59, 1, 5, 101501, "vo_empress_101501_003", "幻境竜后さんの力…すごいわ…\nううん、怖がってる暇なんてないの\n森のみんなを守るためにも…！\n好き勝手したら「めっ」ですからね");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミサト", "", "vo_empress_101501_004", 101501, 3, 4, "", 60, 1, 5, 101502, "vo_empress_101501_004", "あなたと一緒なら\n負けたりなんか絶対にしないわ\n最後の一撃まで、\nがんばりましょうね♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("スズナ", "", "vo_empress_101601_001", 0, 1, 4, "", 61, 1, 5, 101601, "vo_empress_101601_001", "ツヨそーな敵ばっかりで\nテン下げってカンジだけど\nとりま、うちとヒデサイが\n一緒なら乗り越えられるっしょ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("スズナ", "", "vo_empress_101601_002", 0, 1, 4, "", 62, 1, 5, 101601, "vo_empress_101601_002", "あっ、まってヒデサイ\nマントずれてるから直してあげる\n…よし！　こーゆう時こそ\nおしゃれでテン上げしなきゃね♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("スズナ", "", "vo_empress_101601_003", 0, 2, 4, "", 63, 1, 5, 101601, "vo_empress_101601_003", "おにヤバすぎて超わろ～…でもでも\nどうにかやるしかないっしょ～\n勝利のランウェイ遠すぎだけど\nうちら諦めんのはダメだよね～！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("スズナ", "", "vo_empress_101601_004", 101601, 3, 4, "", 64, 1, 5, 101602, "vo_empress_101601_004", "アオハルでバイブス爆上げ♪\n今のうちらは、ムテキだよ～\nハッピーで、もにカワな未来だって\n一緒にゲットするしかないっしょ♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カオリ", "", "vo_empress_101701_001", 0, 1, 4, "", 65, 1, 5, 101701, "vo_empress_101701_001", "歌ったり踊ったり、\nキミと一緒にやりたいことが\nばんないあるからね～！\n絶対に負けられないさ～！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カオリ", "", "vo_empress_101701_002", 0, 1, 4, "", 66, 1, 5, 101701, "vo_empress_101701_002", "ううっ強そうな敵ばっかりさ～！\n長丁場の戦いにはやっぱりこれよ～\nサーターアンダギー！\n栄養付けて平和を守るさ～♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カオリ", "", "vo_empress_101701_003", 0, 2, 4, "", 67, 1, 5, 101703, "vo_empress_101701_003", "うぅ～、幻境竜后、でーじ強いね～\n私たちも引き下がる気はないよ～！\nどんなに時間がかかっても、絶対に\n諦めたりしないさ～！　だよね～？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カオリ", "", "vo_empress_101701_004", 101701, 3, 4, "", 68, 1, 5, 101702, "vo_empress_101701_004", "キミのくれた情熱が、\n私の中で熱く燃え滾ってるよ！\n最高の一撃、キミに見せるさ～！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("イオ", "", "vo_empress_101801_001", 0, 1, 4, "", 69, 1, 5, 101801, "vo_empress_101801_001", "学校生活の邪魔はさせないわ\nだって私、みんなの先生だもの\n明日の授業も世界のことも\n全部守ってみせるんだから！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("イオ", "", "vo_empress_101801_002", 0, 1, 4, "", 70, 1, 5, 101801, "vo_empress_101801_002", "やん！　なんて手ごわい人たちなの\nでも諦めないわ。難しい問題だって\n落ち着いてやればちゃんと解けるの\n戦いも同じよ…いきましょう！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("イオ", "", "vo_empress_101801_003", 0, 2, 4, "", 71, 1, 5, 101803, "vo_empress_101801_003", "これが、幻境竜后さんの力…圧倒\nされちゃいそう。でも、怖がってる\n場合じゃないわ。先生は絶対に、\nここから退かないわ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("イオ", "", "vo_empress_101801_004", 101801, 3, 4, "", 72, 1, 5, 101802, "vo_empress_101801_004", "二人の絆があれば、\n怖いものなんてないわ\n先生と力を合わせて─\nいきましょう♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミミ", "", "vo_empress_102001_001", 0, 1, 4, "", 73, 1, 5, 102003, "vo_empress_102001_001", "す、すごく強そうな人がいっぱい…\nミミ、怖くてぶるぶるしちゃうけど\nでも泣いちゃったりはしないよっ\nおにいちゃんがいっしょだもん…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミミ", "", "vo_empress_102001_002", 0, 1, 4, "", 74, 1, 5, 102003, "vo_empress_102001_002", "プチグリフォンさんもハナちゃんも\nみゅ～ちゃんも…きっとみんな、\nミミのこと応援してくれてるよね\nだからミミも、がんばるよっ…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミミ", "", "vo_empress_102001_003", 0, 2, 4, "", 75, 1, 5, 102003, "vo_empress_102001_003", "あ、あの竜の人…本気になったら、\nすごく強そうだよ…！このままじゃ\nみんなもミミたちも負けちゃう…？\nやだ、ミミそんなのいやだよっ…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミミ", "", "vo_empress_102001_004", 102001, 3, 4, "", 76, 1, 5, 102002, "vo_empress_102001_004", "おにいちゃんがくれた元気、\n今度はミミたちから届けようね\nもう大丈夫、心配しないでって…\n世界中の、大切なお友だちに…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クルミ", "", "vo_empress_102101_001", 0, 1, 4, "", 77, 1, 5, 102101, "vo_empress_102101_001", "怖い人たちがいっぱいですぅ…！\n…でも、みんな頑張ってる…私も\nベルルちゃんみたいに勇気を出して\n…祝福の音を鳴らしましょう！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クルミ", "", "vo_empress_102101_002", 0, 1, 4, "", 78, 1, 5, 102101, "vo_empress_102101_002", "お兄ちゃん、私、がんばりますぅ\n『ロスト』したお父さんたちの\nためにも…！　怖い時こそ前を見て\n戦ってみせますからっ…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クルミ", "", "vo_empress_102101_003", 0, 2, 4, "", 79, 1, 5, 102101, "vo_empress_102101_003", "っ…すごい迫力ですぅ…！\nでも…絶望は必ず乗り越えられる\n胸の中の、希望の音色を信じて…\n逃げたりなんか、しませんよぅ…っ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クルミ", "", "vo_empress_102101_004", 102101, 3, 4, "", 80, 1, 5, 102102, "vo_empress_102101_004", "みんなに勇気を与えるために\n主役にも英雄にもなってみせますぅ\nお兄ちゃんがいてくれるなら\n私はなんでもできるんです…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヨリ", "", "vo_empress_102201_001", 0, 1, 4, "", 81, 1, 5, 102201, "vo_empress_102201_001", "こ、これくらいの敵、問題ないわ！\nほんとはちょっと怖いけど…\nゲームの世界を救うことくらい\nこっちは慣れっこなんだから…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヨリ", "", "vo_empress_102201_002", 0, 1, 4, "", 82, 1, 5, 102201, "vo_empress_102201_002", "ここで私たちが負けたら、\n世界が終わっちゃうなんて…\n絶対に認めるわけにはいかないわ！\nアンタも覚悟決めなさいよっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヨリ", "", "vo_empress_102201_003", 0, 2, 4, "", 83, 1, 5, 102203, "vo_empress_102201_003", "ここからが本当の戦いってこと？\nならもう、とことんやってやるわ！\nゲーマーってのは、敵が手強いほど\n燃えてくる生き物なのよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヨリ", "", "vo_empress_102201_004", 102201, 3, 4, "", 84, 1, 5, 102202, "vo_empress_102201_004", "絶対に帰りたい理由ができた…\nそう思うだけで、いくらでも力が\n湧いてくるの。これならもう、\n文句なしの勝ち確よねっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アヤネ", "", "vo_empress_102301_001", 0, 1, 4, "", 85, 1, 5, 102301, "vo_empress_102301_001", "私もみんなと一緒に戦うよ！\n悪い人たちはフルスイングで\nあっという間に倒しちゃうから！\n『おうっ！　全員かかってこい！』");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アヤネ", "", "vo_empress_102301_002", 0, 1, 4, "", 86, 1, 5, 102303, "vo_empress_102301_002", "本当はちょっとだけ怖いけど…\nぷうきちもお兄ちゃんも一緒だもん\n力を合わせて世界を守っちゃうよ\n絶対に負けないんだから！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アヤネ", "", "vo_empress_102301_003", 0, 2, 4, "", 87, 1, 5, 102303, "vo_empress_102301_003", "ううっあの人、すごく怖いけど\n逃げないよ、戦うって決めたもん\nね、お兄ちゃん、ぷうきち！\n『ここが踏ん張りどころだぞ！』");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アヤネ", "", "vo_empress_102301_004", 102301, 3, 4, "", 88, 1, 5, 102302, "vo_empress_102301_004", "お兄ちゃんが約束してくれたもん\n今の私ならどんな悪いやつにも\n負けないよ！　宇宙人でもなんでも\n一撃で追い返しちゃうんだから♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("スズメ", "", "vo_empress_102501_001", 0, 1, 4, "", 89, 1, 5, 102503, "vo_empress_102501_001", "大変なことになっちゃいましたね…\nで、でも怖がっていられません！\nお嬢さまのことも、あなたのことも\n私が精一杯お支えします！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("スズメ", "", "vo_empress_102501_002", 0, 1, 4, "", 90, 1, 5, 102503, "vo_empress_102501_002", "世界の命運がかかってますから\nドジなんてしてられません！\n…って、ああっ！　言ったそばから\nまた魔法が暴走しちゃいましたっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("スズメ", "", "vo_empress_102501_003", 0, 2, 4, "", 91, 1, 5, 102503, "vo_empress_102501_003", "す、すごい力です…！\nでもお嬢さまや大切な人をおいて\n逃げるわけにはいきません！\nどこまでもお供します…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("スズメ", "", "vo_empress_102501_004", 102501, 3, 4, "", 92, 1, 5, 102502, "vo_empress_102501_004", "大切な人と力を合わせれば、\nドジな私でも世界を救えるんです！\n世界規模…いえ、宇宙規模の大掃除\n始めちゃいますよ～っ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リン", "", "vo_empress_102601_001", 0, 1, 4, "", 93, 1, 5, 102603, "vo_empress_102601_001", "ええー？　こんだけ人数いるならさ\n一人ぐらいいなくても…\n…って空気じゃないわけね\nはいはい、あたしも働きますよー");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リン", "", "vo_empress_102601_002", 0, 1, 4, "", 94, 1, 5, 102603, "vo_empress_102601_002", "うぅ…あんなのもうバグでしょ！？\nこんな無理ゲーに参戦したんだもん\n終わったらしばらく働かないから！\nダラダラゴロゴロするからね～！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リン", "", "vo_empress_102601_003", 0, 2, 4, "", 95, 1, 5, 102603, "vo_empress_102601_003", "見てよあのビジュアルさー\nまさにラスボスって感じじゃん…\nでも、どんなゲームでもボスは\n倒せるわけだし…はぁ、やるかー");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リン", "", "vo_empress_102601_004", 102601, 3, 4, "", 96, 1, 5, 102602, "vo_empress_102601_004", "ここまで来たら後には退けないし\n正真正銘のラスボス戦ってんなら\nあたしも─気合い入れて\n少しぐらいイイとこ見せないとね！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("エリコ", "", "vo_empress_102701_001", 0, 1, 4, "", 97, 1, 5, 102701, "vo_empress_102701_001", "有象無象のクズ虫が、私たちの\n幸せを阻もうとしているようですね\nあぁ、なんて忌々しいのでしょう…\n残らずすり潰しますわ、クスクス…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("エリコ", "", "vo_empress_102701_002", 0, 1, 4, "", 98, 1, 5, 102701, "vo_empress_102701_002", "クスクス…あら、失礼しましたわ\nこの連中を駆逐すれば、私たちの\n絆はより強く…そんな想像をしたら\n思わず…クスクスクス、クスクス");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("エリコ", "", "vo_empress_102701_003", 0, 2, 4, "", 99, 1, 5, 102703, "vo_empress_102701_003", "あの女…下らない言葉であなた様を\n誑かそうとしたとか。万死に値する\n罪…身の程を思い知らせてやるまで\n決して退きはしませんわ…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("エリコ", "", "vo_empress_102701_004", 102701, 3, 4, "", 100, 1, 5, 102702, "vo_empress_102701_004", "『壊し屋』と呼ばれる私ですが…\n今はこの力、創るために振るいます\nあなた様との愛、未来…\nクスクス…さあ参りましょう…♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("サレン", "", "vo_empress_102801_001", 0, 1, 4, "", 101, 1, 5, 102801, "vo_empress_102801_001", "しっかり頭数揃えてきたわね…\nでもこの程度の力に屈するような\nあたしたちじゃないんだから\nあんたも、サポート頼んだわよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("サレン", 1, "vo_empress_102801_002", 0, 4002, 4, 10000, 102, 1, 3, 102801, "vo_empress_102801_002", "ちょっと！　なんか向こうに\n教育に悪そうなのがいるんだけど！\nあいつは子どもたちの目に入る前に\nあたしたちで倒すわよ。いい？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("サレン", "", "vo_empress_102801_003", 0, 2, 4, "", 103, 1, 5, 102803, "vo_empress_102801_003", "もう、強すぎて参っちゃうわね…\nでも諦めるわけにはいかないわ\nこっちだって守らなきゃいけない\nものがたくさんあるんだから！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("サレン", "", "vo_empress_102801_004", 102801, 3, 4, "", 104, 1, 5, 102802, "vo_empress_102801_004", "いつも以上に負ける気がしないわ\nこれもあんたと気持ちが通じた\nおかげね。あんたが側にいる限り、\nあたしはずっと無敵なんだから！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ノゾミ", "", "vo_empress_102901_001", 0, 1, 4, "", 105, 1, 5, 102903, "vo_empress_102901_001", "この世界が終わっちゃうって…\nアイドル活動も卒業ってコト！？\nファンのみんなが黙ってないよ！\nもちろん私だって…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ノゾミ", "", "vo_empress_102901_002", 0, 1, 4, "", 106, 1, 5, 102903, "vo_empress_102901_002", "どんな強い敵にだって屈しない…\n歌って踊って戦うアイドルになる！\nあの日に誓った願い、私の希望！\n今こそ、果たして見せるんだから！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ノゾミ", "", "vo_empress_102901_003", 0, 2, 4, "", 107, 1, 5, 102903, "vo_empress_102901_003", "幻境竜后…ダンスも歌も、あなたに\nとって価値はないかもしれないけど\n私はこのステージから逃げたり\nなんてしない！　アイドルとして！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ノゾミ", "", "vo_empress_102901_004", 102901, 3, 4, "", 108, 1, 5, 102901, "vo_empress_102901_004", "星を書き換えるなんてすごい発想…\nプロデューサーとか向いてるかも？\nって、今はそんな場合じゃないか！\n覚悟してよね、幻境竜后！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ニノン", "", "vo_empress_103001_001", 0, 1, 4, "", 109, 1, 5, 103001, "vo_empress_103001_001", "ショーグンの天下統一を阻む者は\n誰であろうと許しまセン！\nショーグン！　ここはチューシン\nニノンにお任せアーレー！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ニノン", "", "vo_empress_103001_002", 0, 1, 4, "", 110, 1, 5, 103001, "vo_empress_103001_002", "むむむ…待ち受けているのは強敵\nばかり…それでも退きまセン！\n超烈火之紅蓮旋風で、\nまとめて討ち取ってみせまショウ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ニノン", "", "vo_empress_103001_003", 0, 2, 4, "", 111, 1, 5, 103003, "vo_empress_103001_003", "な、なんて強さ…このままでは、\nワタシたちは負けてしまいます…\n…いいえ。いいえ！　ショーグンの\nためにも、諦めることなど…っ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ニノン", "", "vo_empress_103001_004", 103001, 3, 4, "", 112, 1, 5, 103002, "vo_empress_103001_004", "感じマス、ショーグンの愛を…！\n今ならどんな敵が来ても、\nカッサイ、ボンサイ、\nオチャノコサイサイデース！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シノブ", "", "vo_empress_103101_001", 0, 1, 4, "", 113, 1, 5, 103101, "vo_empress_103101_001", "この世界が、明日を迎えることなく\n滅んでしまうかもしれない…\n運命の岐路が、目の前にあります\n抗えるのは、私たちだけです…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シノブ", "", "vo_empress_103101_002", 0, 1, 4, "", 114, 1, 5, 103101, "vo_empress_103101_002", "何よりも色濃い死の気配が、\n世界に満ちていくのを感じます\nでも、倒れるわけにはいきません\n最後まで戦いましょう、全力で");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シノブ", "", "vo_empress_103101_003", 0, 2, 4, "", 115, 1, 5, 103103, "vo_empress_103101_003", "これほどまでに強大な力なんて…\n占いも、未来は滅びの闇に覆われ\nつつある、と出ています…それでも\n希望を手放すわけには…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シノブ", "", "vo_empress_103101_004", 103101, 3, 4, "", 116, 1, 5, 103101, "vo_empress_103101_004", "命ある者にとって、死の運命は\n決して避けられないもの…\nでも、今この時ではないはずです\n戦いましょう、未来のために…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アキノ", "", "vo_empress_103201_001", 0, 1, 4, "", 117, 1, 5, 103201, "vo_empress_103201_001", "これ以上の狼藉は許しません！\nウィスタリア家の名に懸けて、\nこの世界の人々を守ります…必ずや\n貴人としての役目を果たしますわ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アキノ", "", "vo_empress_103201_002", 0, 1, 4, "", 118, 1, 5, 103201, "vo_empress_103201_002", "互いを利するウィンウィンの関係\nそれが商売の鉄則です。力を振るい\n一方的に望みを押し付けるなんて、\n倒産まっしぐらですわよっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アキノ", "", "vo_empress_103201_003", 0, 2, 4, "", 119, 1, 5, 103203, "vo_empress_103201_003", "幻境竜后…すさまじい力ですわね\n世界を意のままにするという野望も\n決して絵空事ではないのでしょう…\nそれでも私は…諦めませんわよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アキノ", "", "vo_empress_103201_004", 103201, 3, 4, "", 120, 1, 5, 103202, "vo_empress_103201_004", "人々を守ることが力ある者の務め…\nそしてあなたさまと共に生きること\nそれが私の務めであり願いですわ！\nこの想いは、止まりませんわよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("マヒル", "", "vo_empress_103301_001", 0, 1, 4, "", 121, 1, 5, 103301, "vo_empress_103301_001", "こんな舞台で漫才したって\nみんなもお天道さんもどんよりだべ\n安心して笑ってられる世界を\nオラたちで取り戻すど！　おー！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("マヒル", "", "vo_empress_103301_002", 0, 1, 4, "", 122, 1, 5, 103301, "vo_empress_103301_002", "お、おっかねぇ連中だ…！\nでも…スベっちまう怖さに比べりゃ\nマシだべな！　あははっ！\nみんなの笑顔は、オラが守るべ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("マヒル", "", "vo_empress_103301_003", 0, 2, 4, "", 123, 1, 5, 103303, "vo_empress_103301_003", "あの子、芸人として光りそうだべな\n幻境竜后なんて仰々しい名前も…\nノーヴィジョンズノープロブレム！\n…あたた！　激しいツッコミだべ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("マヒル", "", "vo_empress_103301_004", 103301, 3, 4, "", 124, 1, 5, 103302, "vo_empress_103301_004", "逆境も笑顔で切り開く…\nあんちゃんと一緒なら\nできる気がすんだ\nオラたちの芸人魂、見せてやるべ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユカリ", "", "vo_empress_103401_001", 0, 1, 4, "", 125, 1, 5, 103401, "vo_empress_103401_001", "元…ううん、正しき聖騎士として\nここでやらなきゃいつやるのよ…！\n必ずみんなを守りきってみせるわ\n怪我をした人は私のところへ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユカリ", "", "vo_empress_103401_002", 0, 1, 4, "", 126, 1, 5, 103401, "vo_empress_103401_002", "…んぐっ…ごくっ…ぷは～っ♪\nよぉし気合十分らわ～っ！\nこら～幻境竜后～っ！　隠れて\nないでかかってきなさ～い！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユカリ", "", "vo_empress_103401_003", 0, 2, 4, "", 127, 1, 5, 103403, "vo_empress_103401_003", "ひっく…ふぇ？　な、なに……？\nと、とっても大きいのが見えりゅ…\n…なっ、なによこれえぇぇ！\nこ、これが幻境竜后の姿なのぉ～っ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユカリ", "", "vo_empress_103401_004", 103401, 3, 4, "", 128, 1, 5, 103402, "vo_empress_103401_004", "私は無敵らのよ～♪　この世界と\nキミと築く\n素敵な未来のために…幻境竜后！\nぶっとばしてやるわぁ～っ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("キョウカ", "", "vo_empress_103601_001", 0, 1, 4, "", 129, 1, 5, 103603, "vo_empress_103601_001", "ここで私たちが諦めたら、このまま\n世界が終わっちゃう！　そんなの\n絶対ダメです！　負けられません！\n私たちで全部退治しちゃいますよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("キョウカ", "", "vo_empress_103601_002", 0, 1, 4, "", 130, 1, 5, 103603, "vo_empress_103601_002", "うぅ、ふしんしゃがいっぱいです！\n…でも、このくらいへっちゃらです\nお母さんが心配する前に、早く\n片付けておうちに帰りましょう！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("キョウカ", "", "vo_empress_103601_003", 0, 2, 4, "", 131, 1, 5, 103601, "vo_empress_103601_003", "あれが私たちの敵、幻境竜后…\nほ、本当に勝てるんでしょうか…？\n立ってるだけで体が震えて…でも、\n弱気になっちゃダメですよねっ…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("キョウカ", "", "vo_empress_103601_004", 103601, 3, 4, "", 132, 1, 5, 103602, "vo_empress_103601_004", "正直に言うと…まだ少し怖いです\n我慢したって怖くて体が震えます\nでも、あなたがいてくれるから…\n勇気だって同じくらい湧いてきます");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("トモ", "", "vo_empress_103701_001", 0, 1, 4, "", 133, 1, 5, 103701, "vo_empress_103701_001", "滅ぼすための力に、守るための力が\n屈するわけにはいかないよ。\nこの剣の誇りに賭けて、必ず止める\nさあ、来い！　ミクマ流が相手だ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("トモ", "", "vo_empress_103701_002", 0, 1, 4, "", 134, 1, 5, 103701, "vo_empress_103701_002", "追いかけっこでもしようか\n鬼さんこちら♪　…って、まだ\n来るの！？　不意打ちされる側に\nなるのは趣味じゃないんだけどな！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("トモ", "", "vo_empress_103701_003", 0, 2, 4, "", 135, 1, 5, 103701, "vo_empress_103701_003", "踏み込めない…踏み込む隙がない…\n向きあってるだけで精一杯なんて…\nで、でも…こんなところで\n剣を捨てるわけにはっ…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("トモ", "", "vo_empress_103701_004", 103701, 3, 4, "", 136, 1, 5, 103702, "vo_empress_103701_004", "勝機は私の中にあったんだ…！\nあなたとの、\n一番強くて絶対に消えない絆\nそれが、あいつを倒す力をくれる！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シオリ", "", "vo_empress_103801_001", 0, 1, 4, "", 137, 1, 5, 103801, "vo_empress_103801_001", "手ごわい相手ですね…\nでも、不思議と怖くありません\nあなたと力を合わせれば\n何とかなるって信じていますから");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シオリ", "", "vo_empress_103801_002", 0, 1, 4, "", 138, 1, 5, 103801, "vo_empress_103801_002", "あなたの応援で、私の胸に\n愛と希望が満ち溢れています…\n今こそ魔法狩人ピュアリー★シオリ\nに大変身する時なのかも…？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シオリ", "", "vo_empress_103801_003", 0, 2, 4, "", 139, 1, 5, 103803, "vo_empress_103801_003", "とてつもない力ですね…\nでも、諦めたくありません\n何度だって立ち上がってみせます\n今までと同じように…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シオリ", "", "vo_empress_103801_004", 103801, 3, 4, "", 140, 1, 5, 103802, "vo_empress_103801_004", "今の私に怖いものなんてありません\nあなたとの愛の力がありますから♪\n…少し舞い上がり過ぎですかね？\nふふ、気を引き締めてがんばります");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アオイ", "", "vo_empress_104001_001", 0, 1, 4, "", 141, 1, 5, 104001, "vo_empress_104001_001", "進んで目立ちたくはないですけど…\nと、ともっ…友達を守るためなら！\nＢＢ団として、勇気を振り絞って…\n団長さんと一緒に戦います！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アオイ", "", "vo_empress_104001_002", 0, 1, 4, "", 142, 1, 5, 104002, "vo_empress_104001_002", "いいい、一緒に戦う仲間がこんなに\nいてくれるなんて、こ、心強いの\n助太郎～っ！　私も末席で参加し…\nじゃなくてっ！　全力で戦います！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アオイ", "", "vo_empress_104001_003", 0, 2, 4, "", 143, 1, 5, 104003, "vo_empress_104001_003", "ううっ、手も足も声も震えてます…\nで、でも逃げも隠れもしませんよっ\n逃げたらぼっちが廃ります！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アオイ", "", "vo_empress_104001_004", 104001, 3, 4, "", 144, 1, 5, 104002, "vo_empress_104001_004", "私はひとりぼっちじゃない…\n団長さんと繋がった絆があるから\nどんな敵だって怖くないですっ！\n行きましょう、団長さんっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("チカ", "", "vo_empress_104201_001", 0, 1, 4, "", 145, 1, 5, 104203, "vo_empress_104201_001", "やめてくれる気はなさそうです\nそれなら私も、絶対にここを\n動きはしません…！　だって\n私は……ワガママですからっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("チカ", "", "vo_empress_104201_002", 0, 1, 4, "", 146, 1, 5, 104201, "vo_empress_104201_002", "私の唱喚術は人を守るためのもの…\nこの世界の森羅万象を護るための\nもの。今こそ、声の限り歌います\nこの子たちと、あなたと共に！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("チカ", "", "vo_empress_104201_003", 0, 2, 4, "", 147, 1, 5, 104203, "vo_empress_104201_003", "精霊たちが震えてる…今までの\n敵とは訳が違うってことですよね…\n私もここに立っているのが精一杯…\n怖いけど…でも！　退きません…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("チカ", "", "vo_empress_104201_004", 104201, 3, 4, "", 148, 1, 5, 104201, "vo_empress_104201_004", "今なら歌える気がします。ずっと\n探していた、誰かの心を震わせる歌\n幻境竜后…孤独なあなたの心にも\n私たちの歌が届くように…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("マコト", "", "vo_empress_104301_001", 0, 1, 4, "", 149, 1, 5, 104301, "vo_empress_104301_001", "敵さんがどんだけ強くったって\n後には退けねぇんだ！　そうだろ、\nさぁ、覚悟しやがれよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("マコト", "", "vo_empress_104301_002", 0, 1, 4, "", 150, 1, 5, 104301, "vo_empress_104301_002", "くっ、敵の連中、ずいぶんな戦力\n揃えてきやがった。けど、\n数でも気合でも負けやしねぇ！\nあたしが嚙み砕いてやる！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("マコト", "", "vo_empress_104301_003", 0, 2, 4, "", 151, 1, 5, 104303, "vo_empress_104301_003", "幻境竜后とやら…マジで\n洒落になんねえな。だからって\n引き下がるわけにゃいかねえ！\n持ちこたえてやるぜ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("マコト", "", "vo_empress_104301_004", 104301, 3, 4, "", 152, 1, 5, 104302, "vo_empress_104301_004", "どんな強い敵でも\n恐れる必要なんてないよな\nさあ、いっしょに─最大パワーで\nブチのめしてやろうぜっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("イリヤ", "", "vo_empress_104401_001", 0, 1, 4, "", 153, 1, 5, 104401, "vo_empress_104401_001", "ここはいずれわらわが支配する世界\nつまり、わが領地に等しきもの…\n奴らのような不届き者の蛮行、\n見過ごすわけにはいかぬわ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("イリヤ", "", "vo_empress_104401_002", 0, 1, 4, "", 154, 1, 5, 104401, "vo_empress_104401_002", "厳しい戦いになりそうじゃな…\nお主もわらわから離れるでないぞ\nも、もちろん、大人の姿を保つのに\n都合がいいからというだけじゃ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("イリヤ", "", "vo_empress_104401_003", 0, 2, 4, "", 155, 1, 5, 104401, "vo_empress_104401_003", "何とも恐ろしく禍々しい力じゃ…\nだが、我が意志は決して挫けぬ\n高貴なる吸血鬼の誇りに懸けて、\n最後まで戦い抜いてみせようぞ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("イリヤ", "", "vo_empress_104401_004", 104401, 3, 4, "", 156, 1, 5, 104401, "vo_empress_104401_004", "己が誰を敵に回したのかを、\n骨の髄まで知らしめてやろうぞ\nここにいるのは固き絆で結ばれし\n伝説の吸血鬼とその眷属じゃ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クウカ", "", "vo_empress_104501_001", 0, 1, 4, "", 157, 1, 5, 104501, "vo_empress_104501_001", "とっても強そうな敵ですっ…\n当然、攻撃も強烈になるはず…\nドＳさん、ここはどうかクウカに、\n先頭をお任せください！　ぐふふ♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クウカ", "", "vo_empress_104501_002", 0, 1, 4, "", 158, 1, 5, 104501, "vo_empress_104501_002", "安心してドＳさんに虐げてもらう\nためにもクウカは負けられませんっ\nこの世界で一番のドＭとして、\n全力で責められに行ってきますっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クウカ", "", "vo_empress_104501_003", 0, 2, 4, "", 159, 1, 5, 104503, "vo_empress_104501_003", "ううっ、刺激が強すぎますよ…っ\nだけど、ドＭのプライドにかけて\nここで退くわけにはいきませんっ！\nドＳさんのこと、守り抜きます…っ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クウカ", "", "vo_empress_104501_004", 104501, 3, 4, "", 160, 1, 5, 104502, "vo_empress_104501_004", "その視線は、『全部終わったらたっ\nぷり調教してやるからな』という\n意味ですね！　ぐふふっ…♪　負け\nられない理由がまた一つできました");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("タマキ", "", "vo_empress_104601_001", 0, 1, 4, "", 161, 1, 5, 104601, "vo_empress_104601_001", "強そうなやつらが目白押しにゃ～\n短期戦でどうにかならないなら…\n長丁場に向けて、特別価格の\nたい焼きはいかがかにゃ～？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("タマキ", "", "vo_empress_104601_002", 0, 1, 4, "", 162, 1, 5, 104601, "vo_empress_104601_002", "ファントムキャッツは\n狙った獲物を逃がさないにゃ！\nあたしたちの未来を手に入れるまで\nとことんやってやるにゃ～！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("タマキ", "", "vo_empress_104601_003", 0, 2, 4, "", 163, 1, 5, 104603, "vo_empress_104601_003", "にゃにゃっ、これが幻境竜后…\nとんでもない力だにゃ\nでも、ここで逃げたらファントム\nキャッツの名が廃るにゃ～！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("タマキ", "", "vo_empress_104601_004", 104601, 3, 4, "", 164, 1, 5, 104602, "vo_empress_104601_004", "ファントムキャッツにかかれば\nどんなに強い悪党でも\n滅びる運命にゃ！\nとっておきの一撃、キメるにゃ～！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ジュン", "", "vo_empress_104701_001", 0, 1, 4, "", 165, 1, 5, 104701, "vo_empress_104701_001", "全軍展開！　敵の一体たりとも\nこの先へは進ませるな\n苦しいときは、私の背中を見るんだ\n我々は決して折れはしない！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ジュン", "", "vo_empress_104701_002", 0, 1, 4, "", 166, 1, 5, 104701, "vo_empress_104701_002", "少年…\n最前線は危険だが、下がるつもりは\nないのか？　ふふ、やはり強情だな\nならば、私の隣を絶対に離れるな");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ジュン", "", "vo_empress_104701_003", 0, 2, 4, "", 167, 1, 5, 104701, "vo_empress_104701_003", "な…なんだ…この冷たい闘気は…！\nみんな、いったん退がれ！\n安心しろ、ここは私が防ぎきる\n…たとえ…この身に代えても");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ジュン", "", "vo_empress_104701_004", 104701, 3, 4, "", 168, 1, 5, 104701, "vo_empress_104701_004", "幻境竜后、貴様は絶対に勝てないよ\n自分の身以上に、大切な誰かを\n守りたいという、人間の持つ尊い\n想いを、知ることのない貴様は…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミフユ", "", "vo_empress_104801_001", 0, 1, 4, "", 169, 1, 5, 104801, "vo_empress_104801_001", "バイト仲間とこの世界のみんなを\n守るために！　私たちのやるべき\nことはただ一つ！　いいわね？\n─最高の効率で倒すわよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミフユ", "", "vo_empress_104801_002", 0, 1, 4, "", 170, 1, 5, 104801, "vo_empress_104801_002", "相手も数が多いし、短期決戦とは\nいかないわね…って！　早く\n勝たなきゃバイトに遅刻しちゃう\nもっと効率アップしていくわよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミフユ", "", "vo_empress_104801_003", 0, 2, 4, "", 171, 1, 5, 104803, "vo_empress_104801_003", "幻境竜后……本当に圧倒的な力ね\nだからってそう簡単に諦められる\nわけはないわよね。たとえそれが\n非効率的な判断だとしても……！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミフユ", "", "vo_empress_104801_004", 104801, 3, 4, "", 172, 1, 5, 104802, "vo_empress_104801_004", "こんなに迂遠で非効率的な計画を\n立てる敵になんて負けないわ！\n効率を極めた私たちの一撃を\n叩きつけてやりましょう！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シズル", "", "vo_empress_104901_001", 0, 1, 4, "", 173, 1, 5, 104902, "vo_empress_104901_001", "安心していいよ、弟くん♪\n弟くんには指一本触れさせない！\n絶対に弟くんを守るから…だって\nそれがお姉ちゃんの役目だもんね！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シズル", "", "vo_empress_104901_002", 0, 1, 4, "", 174, 1, 5, 104902, "vo_empress_104901_002", "準備はできてる、弟くん？\n不安なら手をつないであげよっか？\n大丈夫、お姉ちゃんと弟くんなら\n悪いやつらを全部倒せるはず♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シズル", "", "vo_empress_104901_003", 0, 2, 4, "", 175, 1, 5, 104903, "vo_empress_104901_003", "幻境竜后…手強そうだね…\nでも諦めないよ、絶対に！\n弟くんとお姉ちゃんの大切な世界\nきっと守り抜いてみせるんだから！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シズル", "", "vo_empress_104901_004", 104901, 3, 4, "", 176, 1, 5, 104902, "vo_empress_104901_004", "お姉ちゃんと弟くんの力を合わせて\n二人の未来を、みんなの未来を\n一緒に守ろっ！　あ、終わったら\nたくさん甘えさせてあげるからね♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミサキ", "", "vo_empress_105001_001", 0, 1, 4, "", 177, 1, 5, 105001, "vo_empress_105001_001", "アブナイキレイなお姉さんはね\n『ふれーばー』だから許されるの！\nこんなメチャクチャにするなんて…\n本物の大人のレディが勝負よ勝負！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミサキ", "", "vo_empress_105001_002", 0, 1, 4, "", 178, 1, 5, 105001, "vo_empress_105001_002", "アタシは全世界代表の\n大人のレディなんだから！\nアンタ！\nしっかりエスコートしてよね！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミサキ", "", "vo_empress_105001_003", 0, 2, 4, "", 179, 1, 5, 105003, "vo_empress_105001_003", "コ、コイツが幻境竜后…っ\n…正直怖いけど…絶対に逃げないわ\n大人のレディのプライドにかけて\n戦い抜いてやるんだから…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミサキ", "", "vo_empress_105001_004", 105001, 3, 4, "", 180, 1, 5, 105002, "vo_empress_105001_004", "終わったらデートよ！　だって…\n約束があった方がやる気出るもん♪\nよーし！　大人のレディとして\n最後はエレガントに決めるわよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミツキ", "", "vo_empress_105101_001", 0, 1, 4, "", 181, 1, 5, 105101, "vo_empress_105101_001", "なんて重圧かしら…でも、あいにく\n私も伊達に修羅場をくぐってないの\nさあ、かかってきなさい！\n裏の人生経験、見せてあげるわ…♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミツキ", "", "vo_empress_105101_002", 0, 1, 4, "", 182, 1, 5, 105101, "vo_empress_105101_002", "私は闇医者である前に科学者なの\nあなたたち、実験に協力してくれる\nわよね？　隻眼の悪魔の名は\n伊達じゃないのよ？　覚悟しなさい");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミツキ", "", "vo_empress_105101_003", 0, 2, 4, "", 183, 1, 5, 105101, "vo_empress_105101_003", "到底不可能に思える挑戦こそ\n科学者の腕の見せどころなのよ\n青い薔薇のごとく、人の信念が\n起こす奇跡を見せてあげるわ…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミツキ", "", "vo_empress_105101_004", 105101, 3, 4, "", 184, 1, 5, 105101, "vo_empress_105101_004", "迷いのない言葉をもらったんだもの\n私だってもう、覚悟を決めたわ\nこの先の未来を君と生きていく…\nそのために全力をぶつけるだけよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リマ", "", "vo_empress_105201_001", 0, 1, 4, "", 185, 1, 5, 105201, "vo_empress_105201_001", "私のお友達をいじめるなら\n相手になるわ！\nたとえ魔物に間違えられても\n絶対にここを引かないから！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リマ", 1, "vo_empress_105201_002", 0, 4002, 4, 10000, 186, 1, 3, 105201, "vo_empress_105201_002", "ね、ねぇ…\nちょっと聞きたいんだけど\n毛皮もないのにあの姿なのよね？\n風邪引いたりしないのかしら？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リマ", "", "vo_empress_105201_003", 0, 2, 4, "", 187, 1, 5, 105201, "vo_empress_105201_003", "ひづめは割れちゃいそうだし…\n毛並みだってボロボロだし…\nでも後ろには彼がいるんだもの\n恋する乙女の負けられない戦いよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リマ", "", "vo_empress_105201_004", 105201, 3, 4, "", 188, 1, 5, 105202, "vo_empress_105201_004", "私はもう恋する女の子じゃないわ…\n王子様の愛を受け取ったお姫様よ！\n彼が私を守ってくれるように\n私が彼を守ってみせるわ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("モニカ", "", "vo_empress_105301_001", 0, 1, 4, "", 189, 1, 5, 105303, "vo_empress_105301_001", "どれほど強大な敵であろうと、\n我々【ヴァイスフリューゲル\nランドソル支部】がいれば安心…\nこら！　皆纏まって行動しろー！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("モニカ", "", "vo_empress_105301_002", 0, 1, 4, "", 190, 1, 5, 105301, "vo_empress_105301_002", "敵戦力は強大無比…だが、\n私たちなら必ず倒せるはずだ！\n白き翼の名のもとに、今こそ\n正義の鉄槌を下してやる！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("モニカ", "", "vo_empress_105301_003", 0, 2, 4, "", 191, 1, 5, 105301, "vo_empress_105301_003", "これが幻境竜后の底力か…\n名にし負う圧倒的な強さだな…\nだが！　長期戦になろうとも必ずや\n私たちが勝利の旗を掲げるのだ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("モニカ", "", "vo_empress_105301_004", 105301, 3, 4, "", 192, 1, 5, 105302, "vo_empress_105301_004", "貴公と一緒ならば\nなんだってできるとも\nさあ、最後の一撃を加えてやろう！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ツムギ", "", "vo_empress_105401_001", 0, 1, 4, "", 193, 1, 5, 105401, "vo_empress_105401_001", "強そうな相手ばかりですけど\nだからなんだっていうんですか！\nほら、騎士さんも気合い入れて！\n一緒に戦いますよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ツムギ", 1, "vo_empress_105401_002", 0, 4002, 4, 10000, 194, 1, 3, 105403, "vo_empress_105401_002", "なんか敵に下着姿…っていうか\nほぼ裸みたいな人いません？\n…え？　あれ趣味なんですか？\nあの人の？　…正気ですか？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ツムギ", "", "vo_empress_105401_003", 0, 2, 4, "", 195, 1, 5, 105403, "vo_empress_105401_003", "世界を作り変えようなんて\n幻境竜后、絶対許せません…！\nあとその服！　そんなに破いて！\nデザイナーが泣いてますよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ツムギ", "", "vo_empress_105401_004", 105401, 3, 4, "", 196, 1, 5, 105401, "vo_empress_105401_004", "私と騎士さんの糸は\n絶対に切れません！\nだから…今ここで\nすべてを終わらせましょう！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アユミ", "", "vo_empress_105501_001", 0, 1, 4, "", 197, 1, 5, 105503, "vo_empress_105501_001", "つ、強そうな人たちばっかり…\n逃げたいくらいだけど、\nそれはダメ。先輩をケガさせない\nためにも、私も頑張らなくちゃ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アユミ", "", "vo_empress_105501_002", 0, 1, 4, "", 198, 1, 5, 105501, "vo_empress_105501_002", "私なんかが大それたことを言うのは\n笑われるかも…でも…！\n先輩を守るために、\n世界を守ってみせます…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アユミ", "", "vo_empress_105501_003", 0, 2, 4, "", 199, 1, 5, 105503, "vo_empress_105501_003", "な、なんて大きさ、存在感…！\nまるで私とは真逆の人…\nこうして立ってるだけで、\n私、消えちゃいそうです～っ…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アユミ", "", "vo_empress_105501_004", 105501, 3, 4, "", 200, 1, 5, 105502, "vo_empress_105501_004", "先輩がそばにいてくれる…\nそれだけで勇気が湧いてきて\n前へ進む力がもらえるんです\n行きましょう、先輩！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ルカ", "", "vo_empress_105601_001", 0, 1, 4, "", 201, 1, 5, 105601, "vo_empress_105601_001", "雁首並べてよくもまあ…\nこりゃ長丁場になりそうだ\n釣りと同じくじっくり腰を据えて\n勝負しようじゃないか");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ルカ", "", "vo_empress_105601_002", 0, 1, 4, "", 202, 1, 5, 105601, "vo_empress_105601_002", "世界の危機とあっちゃあ\nアタシたち黄昏時の住人でも\n黙っちゃいられないね！\nひとっ働きさせてもらおうかい！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ルカ", "", "vo_empress_105601_003", 0, 2, 4, "", 203, 1, 5, 105603, "vo_empress_105601_003", "へぇ、これが幻境竜后かい…\nたいそうな強さだけど、アタシも\nここで退くわけにはいかないんだ\n心に差した刃に懸けて、いくよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ルカ", "", "vo_empress_105601_004", 105601, 3, 4, "", 204, 1, 5, 105602, "vo_empress_105601_004", "刀も恋も揃ったアタシは天下無双！\nお前さんが側にいてくれれば、\nどんな巨悪にだって勝てるよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ペコリーヌ", "", "vo_empress_105801_001", 0, 1, 4, "", 205, 1, 5, 105803, "vo_empress_105801_001", "また一緒に、みんなで\nおいしいごはんを食べるために！\nわたしたちは、絶対に負けません！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ペコリーヌ", 1, "vo_empress_105801_002", 0, 4003, 4, 10000, 206, 1, 3, 105801, "vo_empress_105801_002", "フレイヤさんだけじゃなく、\n覇瞳皇帝やミロクまで！\n長丁場になりそうです…\n栄養補給はしっかりしましょうね！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ペコリーヌ", "", "vo_empress_105801_003", 0, 2, 4, "", 207, 1, 5, 105803, "vo_empress_105801_003", "これが、幻境竜后の力…\nやばいですね。正直、どうやって\n止めればいいのか分かりません\nでもここで引き下がるわけには…っ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ペコリーヌ", "", "vo_empress_105801_004", 105801, 3, 4, "", 208, 1, 5, 105802, "vo_empress_105801_004", "あなたの愛情でお腹いっぱいの\n無敵ペコリーヌ参上です☆\nわたしたちの明日を、この世界を\n全力全開で取り戻しましょう！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("コッコロ", "", "vo_empress_105901_001", 0, 1, 4, "", 209, 1, 5, 105903, "vo_empress_105901_001", "みなさまとのおいしいごはんのため\n負けるわけにはまいりません\n主さま、お背中はお任せください\nわたくしがお守りいたします！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("コッコロ", "", "vo_empress_105901_002", 0, 1, 4, "", 210, 1, 5, 105905, "vo_empress_105901_002", "敵は強大…ですが、心強い仲間の\nみなさまが一緒でございます\n…全員主さまとお知り合いなのは\n未だに信じられませんが…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("コッコロ", "", "vo_empress_105901_003", 0, 2, 4, "", 211, 1, 5, 105903, "vo_empress_105901_003", "まだこのような力が…！？\n主さま、ここはお下がりください\nたとえこの身に何があろうと、\nあなただけはお守りいたします…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("コッコロ", "", "vo_empress_105901_004", 105901, 3, 4, "", 212, 1, 5, 105902, "vo_empress_105901_004", "主さまとの絆がある限り\nわたくしは絶対に負けません！\nいついかなるときも、何があろうと\nわたくしが導いてみせます！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("キャル", 1, "vo_empress_106001_001", 0, 4005, 4, 10000, 213, 1, 3, 106001, "vo_empress_106001_001", "また陛下と戦うのね…大丈夫、一番\n大事なものが何なのかは分かってる\n…だから、あたしも負けないわ\n─陛下、よろしくお願いします！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("キャル", "", "vo_empress_106001_002", 0, 1, 4, "", 214, 1, 5, 106003, "vo_empress_106001_002", "この世界を好き勝手しようだなんて\nそういう連中に人生振り回されるの\nこちとらもううんざりなのよ！\n全員ぶっ飛ばしてやるんだから！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("キャル", "", "vo_empress_106001_003", 0, 2, 4, "", 215, 1, 5, 106003, "vo_empress_106001_003", "なんなのよあの力、反則でしょ…\nだけどさ、どんなに怖くたって\nあたしはここから退かないわ\n他に行くとこも、ないんだからっ…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("キャル", "", "vo_empress_106001_004", 106001, 3, 4, "", 216, 1, 5, 106002, "vo_empress_106001_004", "絆の力でパワーアップ、なんて\nガラじゃないと思ってたけど…\n今だけは調子に乗らせてもらうわ\nもう負ける気がしないってねっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ノウェム", "", "vo_empress_106101_001", 0, 1, 4, "", 217, 1, 5, 106102, "vo_empress_106101_001", "晶に直してもらって\n天楼覇断剣も新品同然だ！\n気合い入れていくぞオクトー！\nはーっはっはっはー！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ノウェム", "", "vo_empress_106101_002", 0, 1, 4, "", 218, 1, 5, 106101, "vo_empress_106101_002", "真那、覚悟しとけよ！\nオマエが積み上げてきた悪事…\nこの大悪党がまとめて\nぶっ壊してやるからな！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ノウェム", "", "vo_empress_106101_003", 0, 2, 4, "", 219, 1, 5, 106103, "vo_empress_106101_003", "今までの借り…ここでまとめて\n返してやるって、決めてたんだ\nオマエだけは絶対に、許さない\n…オマエが、どれだけ強くても…っ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ノウェム", "", "vo_empress_106101_004", 106101, 3, 4, "", 220, 1, 5, 106102, "vo_empress_106101_004", "大悪党のプリンセス？\nなんだかよくわからないけど──\nとにかく、あの化け物ぶった斬りに\n行くぞ！　ついてこい！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シェフィ", "", "vo_empress_106401_001", 0, 1, 4, "", 221, 1, 5, 106401, "vo_empress_106401_001", "絶対に負けられない戦いね\nおいしいごはんと、本当の\nハッピーエンドのために\n気を引き締めていきましょう");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シェフィ", 1, "vo_empress_106401_002", 0, 4004, 4, 10000, 222, 1, 3, 106403, "vo_empress_106401_002", "ミロク…まだ生きていたのね…！\nあの男は私が相手するわ\n兄さんの分もまとめて、\n今ここで借りを返さないと！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シェフィ", "", "vo_empress_106401_003", 0, 2, 4, "", 223, 1, 5, 106401, "vo_empress_106401_003", "こんな力を隠してたなんて…！\n…まだよ。まだ諦めないわ\nどんな方法を使ってでも\nみんなだけは助けてみせる…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シェフィ", "", "vo_empress_106401_004", 106401, 3, 4, "", 224, 1, 5, 106402, "vo_empress_106401_004", "不思議ね…あなたとの思い出で\n全身に力が満ちていくような気持ち\n…私たちが紡いできた絆を\n幻境竜后に見せてやりましょう");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カヤ", "", "vo_empress_106501_001", 0, 1, 4, "", 225, 1, 5, 106501, "vo_empress_106501_001", "おまえら、ケンカ売りたいんだろ？\nこの世界そのものに！\nならこっち向けよ。喧嘩屋のオレが\nまとめて買ってやるぜ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カヤ", "", "vo_empress_106501_002", 0, 1, 4, "", 226, 1, 5, 106501, "vo_empress_106501_002", "オレがドラゴン族なのも、\nこんな力を持ってるのも…きっと\n今日、この時のためだったんだ\nそうだろ？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カヤ", "", "vo_empress_106501_003", 0, 2, 4, "", 227, 1, 5, 106503, "vo_empress_106501_003", "ウソだろ…オレが竦んじまってる…\nアイツのあの赤い眼から、眼を\nそらすんじゃねぇ…！　ドラゴン族\nのケンカ最強は…オレ様だろッ…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カヤ", "", "vo_empress_106501_004", 106501, 3, 4, "", 228, 1, 5, 106501, "vo_empress_106501_004", "自分の力に、ずっとビビッてた\nでも今は何よりこの力を頼もしく\n感じるぜ。テメェをぶっ倒し…\n明日を迎えるための力がなァ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("イノリ", "", "vo_empress_106601_001", 0, 1, 4, "", 229, 1, 5, 106603, "vo_empress_106601_001", "どきやがれです！　最強ギャングが\nおまえのシマ分捕りにきたですよ！\nこんだけ仲間がいりゃ楽勝ですね♪\n尻尾巻いて逃げ出しやがれです！！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("イノリ", "", "vo_empress_106601_002", 0, 1, 4, "", 230, 1, 5, 106601, "vo_empress_106601_002", "あっちもゾロゾロつれてきやがり\nましたね…へんっ、このあたしが\nビビビビるとでもおお思うですか\n…お、お兄さん、どどどこです？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("イノリ", "", "vo_empress_106601_003", 0, 2, 4, "", 231, 1, 5, 106603, "vo_empress_106601_003", "…！　あたしと同じドラゴン族？\nボスをプリンセスナイトに従えて\nたとか…へんっ、信じねーです！\nまあボスより性悪そ…ぴゃああっ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("イノリ", "", "vo_empress_106601_004", 106601, 3, 4, "", 232, 1, 5, 106602, "vo_empress_106601_004", "ふっふっふ～ん！　熱い力が\nどんどん溢れてくるですよっ！\nさあ、懲らしめてやるですっ！\nおしりペンペンですよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ホマレ", "", "vo_empress_106701_001", 0, 1, 4, "", 233, 1, 5, 106701, "vo_empress_106701_001", "ふふっ、強そうな子がいっぱいだね\nそれじゃあ、誰が一番か決めよっか\nヴィーちゃんのプリンセスナイトで\n歴代最強は誰なのかを、ね♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ホマレ", "", "vo_empress_106701_002", 0, 1, 4, "", 234, 1, 5, 106701, "vo_empress_106701_002", "ヴィーちゃんてば、そんな子たちと\n一緒にいるほうが楽しいんだ～？\nじゃ、私たちも見せつけないとだね\n遠慮なくやっちゃおう☆　あははっ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ホマレ", "", "vo_empress_106701_003", 0, 2, 4, "", 235, 1, 5, 106703, "vo_empress_106701_003", "これが、ヴィーちゃんの本気…\nとってもとってもすごいなぁ\n怖がりだからこそ、そんなに\n強くなれちゃったのかな…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ホマレ", "", "vo_empress_106701_004", 106701, 3, 4, "", 236, 1, 5, 106702, "vo_empress_106701_004", "残念だけど、ヴィーちゃん…\nもうゲームオーバーみたいだよ\nあなたとのどんなゲームも私には…\n全部ドキドキして、楽しかったな");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ラビリスタ", "", "vo_empress_106801_001", 0, 1, 4, "", 237, 1, 5, 106802, "vo_empress_106801_001", "毎度、予想を超える困難ばかり\n押し寄せてくるんだからさ～\nま、アタシと少年が居る以上、\n好きにはさせないよ、ってね！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ラビリスタ", 1, "vo_empress_106801_002", 0, 4005, 4, 10000, 238, 1, 3, 106801, "vo_empress_106801_002", "よりによって真那まで相手かぁ…\nこりゃ一筋縄じゃいかなそうだ\n誰に対応するかは任せるけど、\n真那を相手取るなら頼ってよ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ラビリスタ", "", "vo_empress_106801_003", 0, 2, 4, "", 239, 1, 5, 106801, "vo_empress_106801_003", "当然、奥の手も用意してくるよね\n次から次へと用意周到だこと…\nとはいえこっちも負けられない\nこの難局の突破口を探すとしよう！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ラビリスタ", "", "vo_empress_106801_004", 106801, 3, 4, "", 240, 1, 5, 106802, "vo_empress_106801_004", "七冠…しかも幻境竜后が相手なら\n手は抜けそうにもないね\nはは、でもアタシたちならきっと\n乗り越えられーる！　だよね少年♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ネネカ", 1, "vo_empress_107001_001", 0, 4005, 4, 10000, 241, 1, 3, 107001, "vo_empress_107001_001", "真那…ふふ、こんなところで相対\nすることになるとは。いつぞやの\n借り、返してあげますよ。用意は\nいいですね？　マサキも、貴方も");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ネネカ", "", "vo_empress_107001_002", 0, 1, 4, "", 242, 1, 5, 107001, "vo_empress_107001_002", "数で私たちを圧倒しようなど…\n底の浅い戦略ですね。返り討ちに\nしてあげましょう…この世界を\nまだ失うわけにはいきませんから");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ネネカ", "", "vo_empress_107001_003", 0, 2, 4, "", 243, 1, 5, 107001, "vo_empress_107001_003", "この力…計算外ではありますが\nそれは予想外という意味では\nありません。ええ、楽しみましょう\n不可能を解く、方程式の探求を");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ネネカ", "", "vo_empress_107001_004", 107001, 3, 4, "", 244, 1, 5, 107002, "vo_empress_107001_004", "特等席で観察させてもらいましょう\n貴方の『心』という変数が\n『レジェンドオブアストルム』に\nどのような影響を与えるのかを…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クリスティーナ", "", "vo_empress_107101_001", 0, 1, 4, "", 245, 1, 5, 107101, "vo_empress_107101_001", "クリスティーナさんのご登場だよ☆\nあっははは……☆　またとない宴だ\n心行くまで愉しもうじゃあないか\n血で血を洗うダンス…滾るな♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クリスティーナ", 1, "vo_empress_107101_002", 0, 4005, 4, 10000, 246, 1, 3, 107101, "vo_empress_107101_002", "真那さまがお出ましか…ワタシは\n本当に運がいいと見える♪　本気で\n刃を交える機会が巡ってくるなど\n願ってもない幸運だよ☆");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クリスティーナ", "", "vo_empress_107101_003", 0, 2, 4, "", 247, 1, 5, 107103, "vo_empress_107101_003", "…ここで退くなど興冷めだろう？\nたとえ足が竦んだとしても…退屈に\n食われるよりもよほどいい！\n最後まで愉しみつくしてやるさ…☆");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クリスティーナ", "", "vo_empress_107101_004", 107101, 3, 4, "", 248, 1, 5, 107102, "vo_empress_107101_004", "誤算だったなあ、『幻境竜后』\n他の者ならいざ知らず…\nキサマを殺せる唯一の力\n手にしたのはこの『誓約女君』だ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クロエ", "", "vo_empress_110801_001", 0, 1, 4, "", 249, 1, 5, 110801, "vo_empress_110801_001", "ざーす。世界を救う系の光バイトで\n来たんすけど…あ、説明とかは\n大丈夫っす。慣れてるんでノリで\n入れます─おのれ世界の敵め！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クロエ", 1, "vo_empress_110801_002", 0, 4005, 4, 10000, 250, 1, 3, 110801, "vo_empress_110801_002", "なっつ、狐のねえさんいるじゃん\nまだ現役で悪モンやってたんだ\nてか中ボスポジに降格してるくね？\n世界の敵界隈、意外とせちがれーな");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クロエ", "", "vo_empress_110801_003", 0, 2, 4, "", 251, 1, 5, 110803, "vo_empress_110801_003", "なんかヤベーの出てきたな…\nこのカンジ、若干最悪っていうか\nぶっちゃけ流れ変わったくない？\nこっから捲るのは…結構ダルいわ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クロエ", "", "vo_empress_110801_004", 110801, 3, 4, "", 252, 1, 5, 110802, "vo_empress_110801_004", "ちょ、聞いて敵、ウケんだけど\nなんかうち主人公だったみたいだわ\n山場でヒロインに力託され系のやつ\nてわけで、勝ち確いただきでーす");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("チエル", "", "vo_empress_110901_001", 0, 1, 4, "", 253, 1, 5, 110901, "vo_empress_110901_001", "ちぇるーん☆　ボス敵のみんな～！\n初めまして＆お久しブリリアント！\n世界の美少女ちえるんでっす！\n今からぼっこぼこにしてあげるね！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("チエル", "", "vo_empress_110901_002", 0, 1, 4, "", 254, 1, 5, 110901, "vo_empress_110901_002", "クリスＰの敵はカルミナの敵！\nカルミナの敵はなかよし部の敵！\nツアー全通めざして戦います！\n現場の平和はチエルが守る！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("チエル", "", "vo_empress_110901_003", 0, 2, 4, "", 255, 1, 5, 110903, "vo_empress_110901_003", "あ、あのう…ヤバくないです？\n敵のねえさん、急に年末歌合戦の\nラスボス衣装みたくなりましたけど\nえ、どーしよ…揚げます白旗？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("チエル", "", "vo_empress_110901_004", 110901, 3, 4, "", 256, 1, 5, 110902, "vo_empress_110901_004", "世界の敵さん、ごめんちゃい！\nなんか愛だか絆だかの超理論的な\nアレでチエル覚醒しちゃいました！\nちぇるっと終わらせてあげますね！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユニ", "", "vo_empress_111001_001", 0, 1, 4, "", 257, 1, 5, 111001, "vo_empress_111001_001", "世界の危機だって？　何度目だね？\nざまあみろだよ、勝手に滅べば…\nなに、地球の危機？　この箱庭の\n話ではなく？　何ソレ一大事！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユニ", "", "vo_empress_111001_002", 0, 1, 4, "", 258, 1, 5, 111001, "vo_empress_111001_002", "お、おい…敵が多すぎないか…？\n端の方でわちゃわちゃしてるだけの\n数合わせ要員として来たのだが…\nどういう事だ、聞いてた話と違うぞ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユニ", "", "vo_empress_111001_003", 0, 2, 4, "", 259, 1, 5, 111003, "vo_empress_111001_003", "あばば…なんだ、あの奇怪な姿は…\nあれが理系をこじらせた者の末路か\n宇宙暗黒理系女…どうしてあんなに\nなるまで放っておいたんだ…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユニ", "", "vo_empress_111001_004", 111001, 3, 4, "", 260, 1, 5, 111002, "vo_empress_111001_004", "はん、驕ったな理系の女王よ\n世界は君が思うほど四角くない\n高機能計算機の弾いた数字ごときで\nぼくと彼の行間までは測れまいよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クレジッタ", "", "vo_empress_118001_001", 0, 1, 4, "", 261, 1, 5, 118001, "vo_empress_118001_001", "ですからわたくしは商人で、\n戦いなどは不向き…などと\n言ってる場合ではありませんわね！\n参りますわよ、我が陛下のために！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クレジッタ", "", "vo_empress_118001_002", 0, 1, 4, "", 262, 1, 5, 118003, "vo_empress_118001_002", "ああもうはあもう、あっちこっち\n滅茶苦茶にしてくださってからに！\n復興費用の賠償はどなたに\n請求すればよろしいのかしら！？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クレジッタ", "", "vo_empress_118001_003", 0, 2, 4, "", 263, 1, 5, 118003, "vo_empress_118001_003", "でっか！？　でっっっっか！！！\n幻境竜后でしたかしら！？\nなんなんですのあの高層建築な方、\n建築基準法違反ですわよ～っ！？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クレジッタ", "", "vo_empress_118001_004", 118001, 3, 4, "", 264, 1, 5, 118002, "vo_empress_118001_004", "ホーッホッホッホ！　幻境竜后さん\n貴方にはいらっしゃるのかしら！\n利害でなくその理想のために\n命を賭ける、真実の忠臣が！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ランファ", "", "vo_empress_118101_001", 0, 1, 4, "", 265, 1, 5, 118101, "vo_empress_118101_001", "恐ろしくて強そうな音が…たくさん\nでも…きっと、大丈夫。あなたや、\nミソラちゃん…みんなが一緒で…\nあたたかい音も、たくさんだもの…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ランファ", "", "vo_empress_118101_002", 0, 1, 4, "", 266, 1, 5, 118101, "vo_empress_118101_002", "緊張、してる…？　そ、それなら、\nわたしに、任せて…わたし、歌を、\n歌うわね…聴けばきっと、いつも\n通りの力を、出せると思うから…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ランファ", "", "vo_empress_118101_003", 0, 2, 4, "", 267, 1, 5, 118103, "vo_empress_118101_003", "お、音と声が、すごい…\nなんて…なんて恐ろしいのかしら…\n…？　で、でも…この音。\n幻境竜后も、恐怖…している…？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ランファ", "", "vo_empress_118101_004", 118101, 3, 4, "", 268, 1, 5, 118102, "vo_empress_118101_004", "わたしの歌が、どれほど役立つかは\nわからない…そ、それでもっ、\nあなたの力になりたいの…だから\nわたし、精一杯、歌うわね…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミソラ", 1, "vo_empress_118201_001", 0, 4005, 4, 10000, 269, 1, 3, 118201, "vo_empress_118201_001", "わー、ミロクさんや覇瞳皇帝さんも\nいるじゃないですか★\nそれじゃあわたしのガトリングで\nご挨拶といきましょっか♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミソラ", "", "vo_empress_118201_002", 0, 1, 4, "", 270, 1, 5, 118201, "vo_empress_118201_002", "騎士さんと力を合わせればどんな\n敵もほにゃららら～★　って感じで\nなんとかなると思うんですよねー\nほら、主人公補正ってやつで♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミソラ", "", "vo_empress_118201_003", 0, 2, 4, "", 271, 1, 5, 118202, "vo_empress_118201_003", "復讐って、イイコトですかね？\n悪いコトですかね？まぁとりあえず\nぶっ壊してから考えましょうか\nね、幻境竜后さん─");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ミソラ", "", "vo_empress_118201_004", 118201, 3, 4, "", 272, 1, 5, 118202, "vo_empress_118201_004", "騎士さんに選んでもらっちゃいまし\nたし、いらない縁とはバイバイした\nいんですよねー♪　ってわけで、\nここで終わりにさせてもらいます★");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カリン", "", "vo_empress_118501_001", 0, 1, 4, "", 273, 1, 5, 118501, "vo_empress_118501_001", "みなさんの力を信じて、\n私も全力でサポートします\n連携と創意工夫があれば、きっと\nこの難局も乗り越えられます！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カリン", "", "vo_empress_118501_002", 0, 1, 4, "", 274, 1, 5, 118502, "vo_empress_118501_002", "過去最大級の強敵が現れました！\nギルド管理協会を代表して…\nあなたに討伐を依頼します！\n報酬はお望みのままに、ですよ♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カリン", "", "vo_empress_118501_003", 0, 2, 4, "", 275, 1, 5, 118503, "vo_empress_118501_003", "…っ。さすがの強敵ですね…\nだからこそ、焦りは禁物…です\nあらゆる事態を想定して、ギルドの\nみなさんを支援するのが私の仕事…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カリン", "", "vo_empress_118501_004", 118501, 3, 4, "", 276, 1, 5, 118502, "vo_empress_118501_004", "あなたと共に進めば\nどんな壁も越えられます\n私の、大切な人の無事を信じて…\n今こそ全力を尽くします！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ネビア", "", "vo_empress_118601_001", 0, 1, 4, "", 277, 1, 5, 118601, "vo_empress_118601_001", "あんな奴らを野放しにしてたら\nこの世界が滅茶苦茶にされちゃう！\nでもまぁこれはこれでチャンスよ♪\n最っ高の悪戯の標的にしてあげる！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ネビア", "", "vo_empress_118601_002", 0, 1, 4, "", 278, 1, 5, 118601, "vo_empress_118601_002", "私はただのガイド妖精、みんなに\n比べれば大した力も持ってない…\nでも悪戯妖精なりの意地があんのよ\nあいつらに一泡吹かせてやるわ♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ネビア", "", "vo_empress_118601_003", 0, 2, 4, "", 279, 1, 5, 118603, "vo_empress_118601_003", "幻境竜后、なんて力の持ち主なの\n正直きっついわ…でもまだやれる\n私はデータよ、壊れたって\nあんたを守る壁くらいにはなれる…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ネビア", "", "vo_empress_118601_004", 118601, 3, 4, "", 280, 1, 5, 118602, "vo_empress_118601_004", "覚悟しなさいっ！\n出来損ないの悪戯妖精をなめたら\n痛い目に遭うって教えてあげる\nさぁ、最高のショーの始まりよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヴァンピィ", "", "vo_empress_122301_001", 0, 1, 4, "", 281, 1, 5, 122303, "vo_empress_122301_001", "むー！　いたずらっこの暴れんぼ\nさんたちは、ヴァンピィちゃんが\nきつーくおしおきしちゃうよ！\n真祖のおつとめですから！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヴァンピィ", "", "vo_empress_122301_002", 0, 1, 4, "", 282, 1, 5, 122302, "vo_empress_122301_002", "けんぞくはヴァンピィちゃんの\n背中に隠れてなさいっ。え？\n背中を守りたい？　うん、それなら\nよろしい！　一緒だよ、けんぞく！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヴァンピィ", "", "vo_empress_122301_003", 0, 2, 4, "", 283, 1, 5, 122303, "vo_empress_122301_003", "幻境竜后？　ふーんだ！\nベスちゃんのほーが、ずーっと\n強くてカッコいいですし！\nいくよっ、けんぞくぅ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヴァンピィ", "", "vo_empress_122301_004", 122301, 3, 4, "", 284, 1, 5, 122302, "vo_empress_122301_004", "ここはみんなの『いばしょ』！\n壊しちゃうなんて、許さないもん\nヴァンピィちゃん、本気で怒ったよ\nやっちゃうよ、けんぞく！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アメス", "", "vo_empress_123001_001", 0, 1, 4, "", 285, 1, 5, 123002, "vo_empress_123001_001", "ほら、あんたは余計な心配しないの\nあいつらに好き勝手させないように\n全力でぶつかっていくだけよ\nあたしたちの未来のためにね♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アメス", "", "vo_empress_123001_002", 0, 1, 4, "", 286, 1, 5, 123001, "vo_empress_123001_002", "…あの連中も強くてやばいけど…\n一番やばいのは、こんなにたくさん\n女の子の知り合いがいる\nあんたかもしれないわね…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アメス", "", "vo_empress_123001_003", 0, 2, 4, "", 287, 1, 5, 123003, "vo_empress_123001_003", "なんて相手なの…さすがに想定を\n超えてるわよ…こんなの卑怯よね\nだからってここで逃げやしないわよ\nせめて、あんたを守るくらいは…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アメス", "", "vo_empress_123001_004", 123001, 3, 4, "", 288, 1, 5, 123002, "vo_empress_123001_004", "敵がどれだけ強くたって関係ないわ\nあんたの行く道はあたしが照らす\n迷ったらあたしを見なさい\nどこまでだって導いてあげる！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ネア", "", "vo_empress_123301_001", 0, 1, 4, "", 289, 1, 5, 123301, "vo_empress_123301_001", "『レギオンウォー』思い出すな～\nあん時は敵側だったけどー\n今回は騎士きゅんたちの隣で\nネアおねえちゃんもがんばるぞ～♡");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ネア", "", "vo_empress_123301_002", 0, 1, 4, "", 290, 1, 5, 123301, "vo_empress_123301_002", "だる～、激ヤバなテキばっかじゃん\n騎士きゅんパワー充電しねーと\nおねえちゃんもギリギリかもー\nとりま、ちゅっちゅ♡　してい？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ネア", "", "vo_empress_123301_003", 0, 2, 4, "", 291, 1, 5, 123303, "vo_empress_123301_003", "激ヤバドラゴン、ガチしんどー…\nま、だからって負ける気ねーけど\nこーゆう時こそ、スライムの\n粘り強さの見せ所っしょ～　ね♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ネア", "", "vo_empress_123301_004", 123301, 3, 4, "", 292, 1, 5, 123302, "vo_empress_123301_004", "ンフフフフ～♪　今のアタシ、\n騎士きゅんと一心同体ってやつ～？\nめちゃめちゃアガるわ～♪\n愛の力パねぇ～♡");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クローチェ", "", "vo_empress_126401_001", 0, 1, 4, "", 293, 1, 5, 126401, "vo_empress_126401_001", "ビーッ！　ビーッ！\nあっちもこっちもそっちも\n強そうな人たちでいっぱいですっ！\nセンサーが壊れちゃいそう～っ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クローチェ", "", "vo_empress_126401_002", 0, 1, 4, "", 294, 1, 5, 126401, "vo_empress_126401_002", "世界が大変なことになってますっ！\nでもわたしたちは今までだって、\n大変な戦いを乗り越えてきましたっ\nきっと…ううん、絶対勝てますっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クローチェ", "", "vo_empress_126401_003", 0, 2, 4, "", 295, 1, 5, 126403, "vo_empress_126401_003", "ビビービビビーッ！　…ひゃあっ！\nセンサーが壊れちゃいました…！\nしかも、照準が震えちゃって…\n…これが…この感情が、恐怖…？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クローチェ", "", "vo_empress_126401_004", 126401, 3, 4, "", 296, 1, 5, 126402, "vo_empress_126401_004", "今のわたしたちに、怖いものなんて\nありませんっ！　敵さんがどんなに\n強くても…わたしとナイトさんの\n特別なパワーは、もっと強いです！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ライラエル", "", "vo_empress_126501_001", 0, 1, 4, "", 297, 1, 5, 126501, "vo_empress_126501_001", "ジオ・テオゴニアの姫として\nこの星に生きる一個として\nこれ以上の蹂躙を許すわけには\nいきません。そうですね？　騎士");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ライラエル", 1, "vo_empress_126501_002", 0, 4002, 4, 10000, 298, 1, 3, 126506, "vo_empress_126501_002", "穢らわしい、色狂いの山羊めが\n我が従僕を傀儡としてくれた借り、\n兆倍──否、京倍にして\n返してくれようぞ。崩雷夜天！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ライラエル", "", "vo_empress_126501_003", 0, 2, 4, "", 299, 1, 5, 126503, "vo_empress_126501_003", "幻境竜后。迷いなく、圧倒的な力で\nわたしたちの調和を滅しようとする\nそんな力を、認めたくはないのに…\nなんて、困難な戦いなのでしょう…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ライラエル", "", "vo_empress_126501_004", 126501, 3, 4, "", 300, 1, 5, 126502, "vo_empress_126501_004", "この星には、あなたがいる…\n悪辣な侵略者と戦う理由など、\nただそれだけで十分です\n守りましょう。わたしたちの世界を");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リンド", 1, "vo_empress_127701_001", 0, 4002, 4, 10000, 301, 1, 3, 127701, "vo_empress_127701_001", "あそこにヴルムを傷つけた人が…！\n…騎士さん、絶対勝ちましょうね\nあの人たちのやったこと、私\n絶対ぜったい許しませんから！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リンド", "", "vo_empress_127701_002", 0, 1, 4, "", 302, 1, 5, 127701, "vo_empress_127701_002", "騎士さんたちと出会えたこの世界を\n悪いことになんか使わせません\n作り物だなんて信じられませんけど\n失っちゃいけないものはわかります");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リンド", "", "vo_empress_127701_003", 0, 2, 4, "", 303, 1, 5, 127703, "vo_empress_127701_003", "まだこんな力が残ってるの…！？\n考えなきゃ、私にできること…\n何か…何かないの…！？\nまた私、何もできないの…？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リンド", "", "vo_empress_127701_004", 127701, 3, 4, "", 304, 1, 5, 127702, "vo_empress_127701_004", "あなたが側にいてくれるから、\n私もこうして戦えます\nチョロいって言われてもいいです\n私にとって、大切なひとですから");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヴルム", "", "vo_empress_127801_001", 0, 1, 4, "", 305, 1, 5, 127801, "vo_empress_127801_001", "…正直、サボりとかじゃなくて…\nぜんぜん身体はきついです。でも…\n姉貴やみんなと過ごすこの世界は\n誰にも壊させやしませんから…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヴルム", 1, "vo_empress_127801_002", 0, 4002, 4, 10000, 306, 1, 3, 127801, "vo_empress_127801_002", "騎士さん…アルシャトのこと\nあたしにも一発殴らせてください\nふざけた真似してくれたお礼…\n倍にして返してやりますよ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヴルム", "", "vo_empress_127801_003", 0, 2, 4, "", 307, 1, 5, 127803, "vo_empress_127801_003", "冗談きついです、こんなの…\n勝てっこないじゃないですか\nあたしだってドラゴン族なのに\nこれほどまでに差があるだなんて…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヴルム", "", "vo_empress_127801_004", 127801, 3, 4, "", 308, 1, 5, 127802, "vo_empress_127801_004", "もう後先考えずにいきますよ\n面倒見てくれる人がここにいるので\nあたしと騎士さんが揃えば\n無敵だってとこ見せてやります");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("エリス", 1, "vo_empress_129001_001", 0, 4005, 4, 10000, 309, 1, 3, 129001, "vo_empress_129001_001", "覇瞳皇帝…わたしの邪魔をするなら\nかつてのように、消去するだけ\nミロクも…わたしを草野優衣の\n複製と呼んだこと、後悔させてやる");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("エリス", "", "vo_empress_129001_002", 0, 1, 4, "", 310, 1, 5, 129001, "vo_empress_129001_002", "管理者の座は失っても\nわたしの意志は揺らがない…\n騎士クンの物語を紡ぐために…\nそれが、わたしの全てだから");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("エリス", "", "vo_empress_129001_003", 0, 2, 4, "", 311, 1, 5, 129003, "vo_empress_129001_003", "これが七冠、幻境竜后の全力…\n管理者だったかつてのわたしを、\n超えるほどの脅威…でも、\n騎士クンだけは、守ってみせる…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("エリス", "", "vo_empress_129001_004", 129001, 3, 4, "", 312, 1, 5, 129002, "vo_empress_129001_004", "孤独も絶望も越えてきた\nもうどんな闇にも迷わない\n騎士クンが隣にいる限り\nわたしは、負けない");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アネモネ", "", "vo_empress_129601_001", 0, 1, 4, "", 313, 1, 5, 129601, "vo_empress_129601_001", "リアを──媛を、傷つけたひとたち\n笑ってられるのも今だけです──\nアルラウネの棘の鋭さ、\n教えてあげますから──");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アネモネ", "", "vo_empress_129601_002", 0, 1, 4, "", 314, 1, 5, 129601, "vo_empress_129601_002", "騎士のひと──背中は、任せます\n貴方のこと、\n媛と同じくらい、信じてるので──\n自分でも、びっくりですけど");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アネモネ", "", "vo_empress_129601_003", 0, 2, 4, "", 315, 1, 5, 129603, "vo_empress_129601_003", "私、ずっと抗ってきたんです\nそのために、強くなったはず──\nだから──諦めたく、ないです…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アネモネ", "", "vo_empress_129601_004", 129601, 3, 4, "", 316, 1, 5, 129601, "vo_empress_129601_004", "体が熱くて、思考がまとまらなくて\nなのに負ける気がしない──なんて\nよくわからないです。どうしてか、\n後で教えてください──騎士のひと");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ネフィ＝ネラ", "", "vo_empress_129701_001", 0, 1, 4, "", 317, 1, 5, 129701, "vo_empress_129701_001", "難敵強敵揃い踏みなれど\nわっちらが退く理はありんせん\n騎士殿や、手を携えて此度の争乱\n鎮めて見せましょう也");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ネフィ＝ネラ", "", "vo_empress_129701_002", 0, 1, 4, "", 318, 1, 5, 129701, "vo_empress_129701_002", "今のわっちが萎弱であろうとて\n貴様等如き梟悪に斃される訳には\nゆかぬ也。再び足甲を舐めさせ\n地に臥すまで仕置きを致しんしょう");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ネフィ＝ネラ", "", "vo_empress_129701_003", 0, 2, 4, "", 319, 1, 5, 129703, "vo_empress_129701_003", "我が矜持『不退転』─如何なる敵で\nあろうとも揺らぐ仕儀はなし。斯様\nな邪竜程度、退けむと思い侍りしが\n─難儀な由、残念至極─…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ネフィ＝ネラ", "", "vo_empress_129701_004", 129701, 3, 4, "", 320, 1, 5, 129702, "vo_empress_129701_004", "参りまする也、騎士殿や\n懼るること等何一つ御座りんせん\n唯わっちらの勇儀を以て、此の星の\n明日を再び…掌中に致しんしょう");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヤマト", 1, "vo_empress_130001_001", 0, 4003, 4, 10000, 321, 1, 3, 130001, "vo_empress_130001_001", "─おや、フレイヤじゃないか\nずいぶん様変わりしたようだが\n今の方がアタシとしちゃ好みだね\nお礼参りのしがいもあるってもんさ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヤマト", "", "vo_empress_130001_002", 0, 1, 4, "", 322, 1, 5, 130001, "vo_empress_130001_002", "…フゥン？　あっちもこっちも\n『王家の装備』を持ってるらしいね\n宝の山ってのはこのことかい\nまとめて搔っ攫ってやろうかね…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヤマト", "", "vo_empress_130001_003", 0, 2, 4, "", 323, 1, 5, 130003, "vo_empress_130001_003", "ちっ…、幻境竜后つったかい\n世界を奪おうってのも冗談じゃ\nなさそうだ。…ワカナ、フブキ…\nお前たちだけでも、逃げな…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヤマト", "", "vo_empress_130001_004", 130001, 3, 4, "", 324, 1, 5, 130002, "vo_empress_130001_004", "アタシらの住み家を奪おうだぁ？\nハッ、笑わせてくれるね\n盗賊は盗むモンであって、\n盗まれるモンじゃあないンだよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ワカナ", "", "vo_empress_130101_001", 0, 1, 4, "", 325, 1, 5, 130101, "vo_empress_130101_001", "つ、強そうな人たちがたくさん…\nなのに姉さんもフブキちゃんも\nやる気満々だし…\nわたし、どうすればいいのぉ～っ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ワカナ", "", "vo_empress_130101_002", 0, 1, 4, "", 326, 1, 5, 130101, "vo_empress_130101_002", "きっと、長期戦になりますよね…\nあ、あの…ご飯、食べませんか？\nお腹が空くといけないと思って、\n作ってきたので…よろしければっ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ワカナ", "", "vo_empress_130101_003", 0, 2, 4, "", 327, 1, 5, 130103, "vo_empress_130101_003", "む…むりっ！　無理ですよ～っ！\nあんなおっきいドラゴンなんて、\n勝てるわけないじゃないですかっ\nに、逃げちゃいましょ、ねっ…！？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ワカナ", "", "vo_empress_130101_004", 130101, 3, 4, "", 328, 1, 5, 130102, "vo_empress_130101_004", "と、盗られるぐらいなら盗るのが\n【バンディ・シスターズ】流ですっ\n騎士さん、わたしたちの未来を\n掴み取りにいきましょう…っ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("フブキ", "", "vo_empress_130201_001", 0, 1, 4, "", 329, 1, 5, 130201, "vo_empress_130201_001", "だる～、ささっと片付けてきてよ～\nムリ？　知ってる～だってザコザコ\nお兄さんだもんね♪　しょーがない\n助けてあげよっかな～？きゃはは♡");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("フブキ", "", "vo_empress_130201_002", 0, 1, 4, "", 330, 1, 5, 130201, "vo_empress_130201_002", "あの陰気ダサダサメガネさー、\n仲間集めてチョーシ乗ってねー？\nザコは何匹集まったってザコだって\nフブキちゃんが教えてあげまーす♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("フブキ", "", "vo_empress_130201_003", 0, 2, 4, "", 331, 1, 5, 130203, "vo_empress_130201_003", "ふぇぇ…まじムリ、アイツムリ～！\n全然ラスボスってカンジじゃん！？\nぼくお家かえるぅ～っ！\nお兄さんも一緒にかえろっ、ねっ？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("フブキ", "", "vo_empress_130201_004", 130201, 3, 4, "", 332, 1, 5, 130202, "vo_empress_130201_004", "お兄さん、やる気漲っちゃってる？\nだよねー、世界が滅んじゃったら\nぼくとも永遠のお別れなんだし？\n必死になるのもトーゼンっしょ～♡");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クルル", "", "vo_empress_130901_001", 0, 1, 4, "", 333, 1, 5, 130901, "vo_empress_130901_001", "はわっ！？　すっごくすっごく\n悪そうな人達いっぱいですますぅ！\nかばばん君、警備員モードです！\nぴっぴーーーー！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クルル", "", "vo_empress_130901_002", 0, 1, 4, "", 334, 1, 5, 130901, "vo_empress_130901_002", "この戦いが終わったら、みなさんと\nパークで凱旋パレードですぅ♪\n…ふぇっ？\n気が早いですますか？");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クルル", "", "vo_empress_130901_003", 0, 2, 4, "", 335, 1, 5, 130903, "vo_empress_130901_003", "はわわっ！　幻境竜后さん、\n強そうすぎですっ…でもっ！\nやっと再建したパークも世界も\nぜったい壊させないですよ～っ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クルル", "", "vo_empress_130901_004", 130901, 3, 4, "", 336, 1, 5, 130902, "vo_empress_130901_004", "ヒーローさんのこと、\nクルルの全部でお助けしますです！\nジオ・テオゴニアでも、どんな世界\nでも…ずっと、ず～っとですっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ルイズマリー", "", "vo_empress_132301_001", 0, 1, 4, "", 337, 1, 5, 132301, "vo_empress_132301_001", "なっなんなのよこいつらっ！\nダーリンとの恋路を邪魔する気…？\nそんなことさせないわ…だって、\n二人の恋はエターナルですからっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ルイズマリー", "", "vo_empress_132301_002", 0, 1, 4, "", 338, 1, 5, 132301, "vo_empress_132301_002", "愛情×愛情＝無限大…\n遂に錬金術の神髄に辿り着いたわ…\nさあ…お見舞いしてやりましょう！\n私とダーリンの究極錬成をっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ルイズマリー", "", "vo_empress_132301_003", 0, 2, 4, "", 339, 1, 5, 132303, "vo_empress_132301_003", "あ、あなたがどんなに強くても、\n私は逃げないわ！　ダーリンに\nちょっかいかける奴は絶対に\n許さないって決めてるから…っ！！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ルイズマリー", "", "vo_empress_132301_004", 132301, 3, 4, "", 340, 1, 5, 132302, "vo_empress_132301_004", "悪いけど速攻で終わらせちゃうわ！\n早く帰ってダーリンと心行くまで\n破廉恥な乳繰り合い…じゃなくて！\n愛を確かめ合うんだからっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("イロハ", "", "vo_empress_132401_001", 0, 1, 4, "", 341, 1, 5, 132401, "vo_empress_132401_001", "わわっ、敵がいっぱい！\nこれがクワガタだったら最高…よし\n新種のクワガタって事にしちゃお！\nあははっ！　待て待て～っ！！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("イロハ", "", "vo_empress_132401_002", 0, 1, 4, "", 342, 1, 5, 132401, "vo_empress_132401_002", "あはは、まだまだ出てくるね～！\nなら新しい技いっぱい\n試しちゃおっか…さあ、いくよ！\n──イスルギ流奥義っ！！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("イロハ", "", "vo_empress_132401_003", 0, 2, 4, "", 343, 1, 5, 132401, "vo_empress_132401_003", "あのおねーさんもなかなか良いツノ\n持ってるねえ♪　イロハが勝ったら\nルイちゃんと二人でクワガタ相撲\nごっこやってもらおっと！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("イロハ", "", "vo_empress_132401_004", 132401, 3, 4, "", 344, 1, 5, 132402, "vo_empress_132401_004", "おねーさんがどんなに強くたって\nイロハは絶対に負けない！\nおじちゃんが見ててくれてる時の\nイロハは、サイキョーなんだから！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ソノ", "", "vo_empress_132501_001", 0, 1, 4, "", 345, 1, 5, 132501, "vo_empress_132501_001", "いや無理無理、戦いとか苦手過ぎる\n…でも君となら、奇跡起こせるかも\n…うわやば、今の忘れて\n若者みたいなこと言っちゃったよ…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ソノ", "", "vo_empress_132501_002", 0, 1, 4, "", 346, 1, 5, 132501, "vo_empress_132501_002", "敵、まだいっぱいいるじゃん…\nはあ…残業したくないけど頑張るか\n全部終わったら君からのマッサージ\n期待しとくから、ね");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ソノ", "", "vo_empress_132501_003", 0, 2, 4, "", 347, 1, 5, 132503, "vo_empress_132501_003", "はあ…はあ…幻境竜后だっけ？\nルイちゃんの錬金術より\n出鱈目な強さだね…！\nでもまだまだ諦めない…いくよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ソノ", "", "vo_empress_132501_004", 132501, 3, 4, "", 348, 1, 5, 132502, "vo_empress_132501_004", "こんなに強い敵が相手でも\n諦めなきゃ勝てるんだって\n教えてくれたのは君だよ\nふふ…ありがとね、若者♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("グレイス", "", "vo_empress_133001_001", 0, 1, 4, "", 349, 1, 5, 133001, "vo_empress_133001_001", "うーわ。あっちもこっちも\nボス級だらけじゃないですか\nま、ヴァイオレット姫には\n指一本触れさせませんけどね");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("グレイス", 1, "vo_empress_133001_002", 0, 4001, 4, 10000, 350, 1, 3, 133003, "vo_empress_133001_002", "リーザ…今度こそ、決着の時ね\nいくら頭数を揃えても私は…いえ\n私と騎士氏は絶対に負けないわ\nこの槍で、冥界に送り返してあげる");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("グレイス", "", "vo_empress_133001_003", 0, 2, 4, "", 351, 1, 5, 133003, "vo_empress_133001_003", "ぐっ…圧倒的ですね『幻境竜后』\nですが…決してあきらめません\n私には、生きていてほしい人が\nたくさんいますので…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("グレイス", "", "vo_empress_133001_004", 133001, 3, 4, "", 352, 1, 5, 133002, "vo_empress_133001_004", "とてつもない強敵を前にしてるのに\nまるで恐怖心を感じません…\n…恋とは、心霊現象よりも\n不思議なものらしいですよ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヴァイオレット", "", "vo_empress_133101_001", 0, 1, 4, "", 353, 1, 5, 133101, "vo_empress_133101_001", "恐るべき方々ばかりです…\nですがわたくしは絶対に退きません\nジオ・ニヴルヘルの姫として\nこの世界を守ると決めたのです！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヴァイオレット", 1, "vo_empress_133101_002", 0, 4001, 4, 10000, 354, 1, 3, 133101, "vo_empress_133101_002", "リーザ…どうしてもわたくしたちの\n前に立ちはだかるというのですね\nならばわたくしも覚悟を決めました\nこの手であなたを、倒します…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヴァイオレット", "", "vo_empress_133101_003", 0, 2, 4, "", 355, 1, 5, 133103, "vo_empress_133101_003", "これが、彼女の本気の力…！\n異質で…故に、とても寂しい…\n本当の意味で彼女に届く声が、\nこの世界に存在するのでしょうか…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ヴァイオレット", "", "vo_empress_133101_004", 133101, 3, 4, "", 356, 1, 5, 133102, "vo_empress_133101_004", "あなたとの「繋がり」がある限り\n死が牙を剥くことはありません\n手を取り合い、共に参りましょう\nわたくしたちの未来のために！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("メドゥーサ", "", "vo_empress_133601_001", 0, 1, 4, "", 357, 1, 5, 133601, "vo_empress_133601_001", "フンっ、次から次へと…！　なら\n思う存分、大暴れしてやるから♪\nやっちゃうわよ、メドゥシアナ！\nアンタも！！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("メドゥーサ", "", "vo_empress_133601_002", 0, 1, 4, "", 358, 1, 5, 133601, "vo_empress_133601_002", "どこの誰だか知らないけれど、\nアタシの魔眼でまとめて石に…って\nきゃああああ！　こんなバケモン級\nなら先に教えときなさいよ～っ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("メドゥーサ", "", "vo_empress_133601_003", 0, 2, 4, "", 359, 1, 5, 133603, "vo_empress_133601_003", "な…なんなの、アイツの『眼』…\nでもねっ、アタシはメドゥーサ\nゴルゴーンの、お姉ちゃんの妹よ！\n睨みあいで負けるわけがないわ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("メドゥーサ", "", "vo_empress_133601_004", 133601, 3, 4, "", 360, 1, 5, 133602, "vo_empress_133601_004", "知ってる？　蛇って執念深いのよ\nこの『眼』で見つけてやったわ\n幻境竜后、アンタが一番恐れること\nアタシとこいつが手をつなぐこと！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ホウオウ", "", "vo_empress_134701_001", 0, 1, 4, "", 361, 1, 5, 134701, "vo_empress_134701_001", "この大地と大空を守るため、\n人の子らだけに任せてはおけません\n鳳凰のはばたきで、その野望ごと\n跡形もなく吹き飛ばしましょう！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ホウオウ", "", "vo_empress_134701_002", 0, 1, 4, "", 362, 1, 5, 134701, "vo_empress_134701_002", "さあ皆さん、ここが正念場です！\n私がいれば楽勝圧勝間違いなし！\n…えっ？　私が先頭？　えーと…\nあっちょっと待って押さないで！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ホウオウ", "", "vo_empress_134701_003", 0, 2, 4, "", 363, 1, 5, 134703, "vo_empress_134701_003", "羽が散って、ちっ、力が…\n幻境竜后、やるではないですか…\nしかし、私も不死鳥と呼ばれた身…\nただでやられは…ぴ、ぴよぉぉ～…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ホウオウ", "", "vo_empress_134701_004", 134701, 3, 4, "", 364, 1, 5, 134702, "vo_empress_134701_004", "幻境竜后、でしたか？\nあなたも運のない方ですね\n今の私は輪廻史上最強の鳳凰\nその鱗一つ残さず焼き尽くします！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カノン", "", "vo_empress_134901_001", 0, 1, 4, "", 365, 1, 5, 134901, "vo_empress_134901_001", "ヲ～ッホッホ！　どいつもこいつも\n大層なおツラ構えしてますけどぉ？\nあたくし様の敵じゃありませんわ！\nほら馬ボーン！　お強化なさいな！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カノン", "", "vo_empress_134901_002", 0, 1, 4, "", 366, 1, 5, 134901, "vo_empress_134901_002", "いってぇ～ですわ！　あたくし様の\nお美しいお肌を傷つけましたわね！\nまとめてお成敗して差し上げますわ\nついてらっしゃいな！　馬ボーン！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カノン", "", "vo_empress_134901_003", 0, 2, 4, "", 367, 1, 5, 134903, "vo_empress_134901_003", "なんてタマですの…アースハイドラ\nよりデカいなんて聞いてませんわ！\nでも…ここでお尻尾巻いて逃げる\nなら、死んだ方がマシですわ…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("カノン", "", "vo_empress_134901_004", 134901, 3, 4, "", 368, 1, 5, 134902, "vo_empress_134901_004", "幻境竜后とやら、お覚悟なさいな\nあたくしと馬ボーンの前に立つなど\n100億万年お早いですわ！\n華麗にお成敗して差し上げますわ♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アイラ", "", "vo_empress_135501_001", 0, 1, 4, "", 369, 1, 5, 135501, "vo_empress_135501_001", "来たね、お姉さんの出番ってやつ♪\nキミと一緒に戦えるなんて、あたし\nテンション最高潮だよ！　あははっ\nさ、思いっきり暴れちゃおっか！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アイラ", 1, "vo_empress_135501_002", 0, 4005, 4, 10000, 370, 1, 3, 135501, "vo_empress_135501_002", "あれが…覇瞳皇帝のオリジナルだね\nま、関係ないや。本物でも偽物でも\n今度こそ決着つけてあげるから！\nお姉さんの拳…燃え盛ってるよー！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アイラ", "", "vo_empress_135501_003", 0, 2, 4, "", 371, 1, 5, 135503, "vo_empress_135501_003", "幻境竜后…とんでもない相手だね\nあたしの拳だって届かないかも…\nそれでも、燃え尽きるまで戦うよ\nキミが信じてくれてる限り、ね！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アイラ", "", "vo_empress_135501_004", 135501, 3, 4, "", 372, 1, 5, 135502, "vo_empress_135501_004", "キミがいれば怖いものなし！\nお姉さん今、燃えに燃えてるよっ\n太陽より熱く燃える拳で…\n全部まとめてぶっ飛ばす！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シナツ", "", "vo_empress_135601_001", 0, 1, 4, "", 373, 1, 5, 135601, "vo_empress_135601_001", "どれほどの逆風の中にいても、\n諦めてはならない…そうだろう？\nかつて私が、他でもないキミたちに\nそう教えてもらったんだ…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シナツ", "", "vo_empress_135601_002", 0, 1, 4, "", 374, 1, 5, 135601, "vo_empress_135601_002", "私はこの世界の人々と出会い、\n失ったはずの希望を見つけられた\n今度は私が、皆に希望を届ける番だ\nこの刃、存分に振るわせてくれ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シナツ", "", "vo_empress_135601_003", 0, 2, 4, "", 375, 1, 5, 135603, "vo_empress_135601_003", "幻境竜后…私たちの世界を創造し、\nそして滅ぼそうとした張本人か…！\nその力がどんなに強大だとしても…\n私は…絶対に逃げたりなどしない！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("シナツ", "", "vo_empress_135601_004", 135601, 3, 4, "", 376, 1, 5, 135602, "vo_empress_135601_004", "私の刃に、もはや一片の曇りもない\n皆と生きる未来を守り抜くために\n戦いつづける…ただそれだけだ\n─道を阻む者は全て斬り伏せる！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユキノ", 1, "vo_empress_135801_001", 0, 4001, 4, 10000, 377, 1, 3, 135801, "vo_empress_135801_001", "リ、リ、リーザちゃ…！\nリーザちゃはあてのこと、ヘタレの\nホジナシって思ってっかもだけど…\n前より成長したとこ、見せっから！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユキノ", "", "vo_empress_135801_002", 0, 1, 4, "", 378, 1, 5, 135801, "vo_empress_135801_002", "田舎者で世間知らずなあてだけど…\n騎士さと一緒にいろんなとこ行って\n大切な思い出、いっぱいできたよ…\nだから守りてぇんだ、この世界…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユキノ", "", "vo_empress_135801_003", 0, 2, 4, "", 379, 1, 5, 135803, "vo_empress_135801_003", "あ、あても、ちったぁでけぇけど…\n幻境竜后、で、でっかすぎ…！\nそ、それに竜まで…！　炎浴びたら\nあて、溶けちまうよぅ…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ユキノ", "", "vo_empress_135801_004", 135801, 3, 4, "", 380, 1, 5, 135802, "vo_empress_135801_004", "「あてなんか」なんて、考えね…\n騎士さが信じてくれるなら、\nあてだって自分のこと、信じるよ\nあてと騎士さなら大丈夫、って…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("サツキ", 1, "vo_empress_135901_001", 0, 4001, 4, 10000, 381, 1, 3, 135903, "vo_empress_135901_001", "リザ公…手前ェどの面下げて\n俺の前に出てきやがった\nまァいいさ、何聞いても今更だ\nここで落とし前つけてもらうぜ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("サツキ", "", "vo_empress_135901_002", 0, 1, 4, "", 382, 1, 5, 135901, "vo_empress_135901_002", "いつ死んでもいいなんて\nもう思っちゃいねぇさ\nこの悪玉どもより、図太くしぶとく\n生き抜いてやろうじゃねぇか");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("サツキ", "", "vo_empress_135901_003", 0, 2, 4, "", 383, 1, 5, 135901, "vo_empress_135901_003", "あれが幻境竜后か…\nハンパじゃねェや\nしゃあねぇ、こうなりゃ一丁\n死に花咲かすとするか");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("サツキ", "", "vo_empress_135901_004", 135901, 3, 4, "", 384, 1, 5, 135902, "vo_empress_135901_004", "世界だの未来だの現実だの…\n重いったらありゃしねぇぜ\n潰れるなよ、騎士公\n俺も一緒に担いでやっからさ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アラクネ", "", "vo_empress_136001_001", 0, 1, 4, "", 385, 1, 5, 136001, "vo_empress_136001_001", "騎士さま、どうかご安心を…\nどれだけ厳しい運命が待って\nいたとしても…あなたのことは、\nわたしの糸が必ずお守りします");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アラクネ", 1, "vo_empress_136001_002", 0, 4003, 4, 10000, 386, 1, 3, 136001, "vo_empress_136001_002", "…？　あの金髪の女性、なんだか\n見覚えあるような気が…いえ\n騎士さまの敵は、わたしの敵です\nそれだけです…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アラクネ", "", "vo_empress_136001_003", 0, 2, 4, "", 387, 1, 5, 136003, "vo_empress_136001_003", "あれが幻境竜后さま…\nなんという恐るべき力\n…騎士さま、わたしの後ろに\n一度くらいは、庇えるはずです…");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("アラクネ", "", "vo_empress_136001_004", 136001, 3, 4, "", 388, 1, 5, 136002, "vo_empress_136001_004", "騎士さまという光が、わたしに力を\n与えてくれるのです。ともに未来を\n歩むためにも…この戦いに\n必ず勝ちましょう、騎士さま");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ナーナ", "", "vo_empress_136201_001", 0, 1, 4, "", 389, 1, 5, 136201, "vo_empress_136201_001", "強そうな敵さんがいっぱい～っ！？\nこーなったら、ウルトラとっておき\nドーナツ！　ちょっと湿気てるけど\n…はい騎士ちゃん、あーんっ♪");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ナーナ", "", "vo_empress_136201_002", 0, 1, 4, "", 390, 1, 5, 136201, "vo_empress_136201_002", "ナーナだって頑張れるんだよっ！\n騎士ちゃんに、そう教わったもん！\nだから、すごく怖いけど…でもっ…\nナーナ、逃げたりしないよぉっ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ナーナ", "", "vo_empress_136201_003", 0, 2, 4, "", 391, 1, 5, 136201, "vo_empress_136201_003", "うぅ…あ、足が震えてきちゃった…\nでも動かなきゃ、戦わなきゃっ…\nわかってるのに、でもでもぉ…\nうえぇぇん、やっぱり怖いぃぃ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ナーナ", "", "vo_empress_136201_004", 136201, 3, 4, "", 392, 1, 5, 136202, "vo_empress_136201_004", "今のナーナはよわよわウサギじゃ\nないんだよ。騎士ちゃんのためなら\nどんな敵さんだってやっつけちゃう\nつよつよウサギなんだから！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ルルィ", 1, "vo_empress_136901_001", 0, 4001, 4, 10000, 393, 1, 3, 136903, "vo_empress_136901_001", "リーザ姉しゃまが裏切ったなんて\nあたち、信じたくないでしゅ…！\nだから直接聞きにいきましゅ\n吸盤ぜんぶで捕まえてでも…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ルルィ", "", "vo_empress_136901_002", 0, 1, 4, "", 394, 1, 5, 136901, "vo_empress_136901_002", "姫姉しゃまも騎士しゃんも\nみなしゃん戦ってるんでしゅ\nあたちだって負けましぇん！\n一生懸命がんばりましゅ～！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ルルィ", "", "vo_empress_136901_003", 0, 2, 4, "", 395, 1, 5, 136903, "vo_empress_136901_003", "あ、あの方、こわいでしゅ…！\n丸呑みにされちゃいそうでしゅっ\nうじゅ…がんばりたいでしゅが…\n震えが止まらないでしゅ…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ルルィ", "", "vo_empress_136901_004", 136901, 3, 4, "", 396, 1, 5, 136902, "vo_empress_136901_004", "あたちは強くないでしゅけど\n騎士しゃんとの約束がありましゅ\nだから誰にも負けましぇん！\nいっちょに、守りましゅよ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リリ", "", "vo_empress_139501_001", 0, 1, 4, "", 397, 1, 5, 139501, "vo_empress_139501_001", "これから挑む敵がどれだけ強いと\nしても、勇往邁進していきます\nですからこの戦いでも、兄様の\nおそばで戦わせてくださいませ");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リリ", 1, "vo_empress_139501_002", 0, 4002, 4, 10000, 398, 1, 3, 139503, "vo_empress_139501_002", "幻境竜后の手先、アルシャト…！\nリアさんやヴルム様を陥れた貴方を\n決して許す訳には参りません！\n不倶戴天─ここで成敗致します！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リリ", "", "vo_empress_139501_003", 0, 2, 4, "", 399, 1, 5, 139503, "vo_empress_139501_003", "幻境竜后の力…これほどまでに\n強力無比だとは…で、ですが…\n何があろうとわたくしは兄様を\nお守りします…命に代えても、必ず");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("リリ", "", "vo_empress_139501_004", 125801, 3, 4, "", 400, 1, 5, 139502, "vo_empress_139501_004", "兄様への想いと、重ねてきた大切な\n時間が、たくさんの勇気と限界を\n超える奇跡をくれました。全ての人\nを救うため、参りましょう兄様…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クリア", "", "vo_empress_139601_001", 0, 1, 4, "", 401, 1, 5, 139603, "vo_empress_139601_001", "お兄さん、もし怪我しちゃっても\nすぐに治癒しますからご安心を！\nわたし決めましたから…もう二度と\n自分自身から逃げないって…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クリア", 1, "vo_empress_139601_002", 0, 4002, 4, 10000, 402, 1, 3, 139603, "vo_empress_139601_002", "…アルシャトさん…\n謝ったって許してあげませんよ？\nあなたの前では、わたしちょっと\nいい子じゃいられませんから…っ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クリア", "", "vo_empress_139601_003", 0, 2, 4, "", 403, 1, 5, 139603, "vo_empress_139601_003", "うぅっ…これが本気の幻境竜后…！\n…こんなの勝てっこありませんよ…\n…せめてお兄さんだけでも…なんて\n最後まで…諦めませんからっ…！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("クリア", "", "vo_empress_139601_004", 126001, 3, 4, "", 404, 1, 5, 139601, "vo_empress_139601_004", "お兄さんの気持ちが胸に溢れて…\nあ、えへへ…なんだか視界が\n滲んできちゃいました…♪\nわたしはもう、負けませんよ…っ！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("プレシア", "", "vo_empress_139701_001", 0, 1, 4, "", 405, 1, 5, 139701, "vo_empress_139701_001", "てき、いっぱい、しかも、つよすぎ\nけど、まけないよ\nお兄のほっぺ、たべて\nふるぱわー");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("プレシア", "", "vo_empress_139701_002", 0, 1, 4, "", 406, 1, 5, 139701, "vo_empress_139701_002", "ん\nまだまだ、いける\nお兄、パパ、なかま、いる\nむしゃぶるい");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("プレシア", "", "vo_empress_139701_003", 0, 2, 4, "", 407, 1, 5, 139703, "vo_empress_139701_003", "しょうり、みえない\nせいぎ、まもれない\nそんなの、いや\nあきらめないよ、さいごまで");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("プレシア", "", "vo_empress_139701_004", 126101, 3, 4, "", 408, 1, 5, 139702, "vo_empress_139701_004", "て、つなぐ\nせいめいりょく、たかまる\nぜったいしょうり！");
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES ("ティア", "", "vo_empress_140301_004", 140301, 3, 4, "", 409, 1, 5, 140301, "vo_empress_140301_004", "七冠、幻境竜后──LoAの開発者\nあんたにコワいコト教えてあげるわ\n些細なバグと思って放置したら\nゲームを壊すこともあるってね…♪");
